-- PeaklyPrep: PeaklyTest Aug 2025 — full practice test from the PeaklyTest library (August 2025 form) --------
-- Generated from the PeaklyTest PDF: questions, answer choices, answer keys and explanations.
-- Figures live in public/q/aug25/. Ids are fixed, so running this file again updates the test instead of copying it.

-- PeaklyTest Aug 2025 · Reading & Writing · Module 1
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('c128ce21-9cd3-541e-b08f-656cb1889050', 'PeaklyTest Aug 2025 · Reading & Writing · Module 1', 'Reading & Writing', 'Reading & Writing, Module 1 of the Aug 2025 PeaklyTest · 27 questions · 32 minutes', 32, 140, true, 'PeaklyTest Aug 2025 · Reading & Writing', 1)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('ae9057f7-7685-54da-9c4a-4c73f97e4a10', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'Which choice completes the text with the most logical and precise word or phrase?', '["universal", "elaborate", "illusory", "idealized"]'::jsonb, 1, 'Traditionally, certain features of mosque architecture are nearly _____, such as the mihrab (or niche), which almost all mosques include. But mosques can also be built to reflect a multitude of different architectural styles, as in the case of the Great Mosque of Central Java, which includes elements from the Javanese and Greek revival styles.'),
  ('281482de-ae1f-5b88-a8c5-b5c3cb1c80c7', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'Which choice completes the text with the most logical and precise word or phrase?', '["uncontroversial", "irrelevant", "applicable", "approximate"]'::jsonb, 2, 'The dates that archaeologists assign to most of the colossal sculptures of human heads produced by the Olmec civilization of Mesoamerica are necessarily _____. The majority of the sculptures have been moved from their original context, making precise dating impossible.'),
  ('9b34f9ff-8241-590d-8bfc-7d5130f7a24b', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'Which choice completes the text with the most logical and precise word or phrase?', '["Discrepancies between", "Proclamations of", "Recurrences of", "Affinities between"]'::jsonb, 3, '_____ traditional descriptions of pollination syndromes (suites of floral traits, such as nectar composition and symmetry, hypothesized to have independently evolved as a result of selection pressure exerted by pollinators) and recent empirical observations of floral-trait combinations have led some ecologists to express reservations about the utility of those descriptions.'),
  ('f5023baa-7099-5ec3-918c-9863771bf0bf', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'Which choice best describes the function of the underlined sentence in the text as a whole?', '["It suggests that there are likely fossilized Calamophyton forests from before 390 million years ago.", "It provides two competing views of when the Calamophyton forest likely merged.", "It illustrates how Calamophyton forests likely changed conditions on the land.", "It indicates how fast the Calamophyton forest spread."]'::jsonb, 4, 'Scientists discovered a 390-million-year-old fossilized forest of Calamophyton trees in modern-day England. The scientists believe the emergence of these Calamophyton forests changed the land significantly. <u>For example, the tree roots would have greatly reduced soil erosion, and the accumulated</u> <u>twigs the trees shed likely created new habitats for animal life.</u>'),
  ('759c7174-8af4-56af-b4e4-a0ca4300de52', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'Which choice best describes the main purpose of the text?', '["To present the narrator’s belief that she understands Dot better than Celestine does", "To speculate that when Dot is older, her personality will be like Celestine’s", "To discuss what the narrator and Celestine do to amuse Dot", "To compare the narrator’s physical appearance to the physical appearance of Celestine"]'::jsonb, 5, 'The following text is from Louise Erdrich’s 1986 novel The Beet Queen. The narrator discusses her relationship with her young niece, Dot. Celestine, the narrator’s sister-in-law, is Dot’s mother.

Dot and I had a mental connection, I was sure of it. I understood things about the baby that her mother could not accept. For instance, she was never meant to be a baby. Dot was as impatient with babyhood as I. She tried at once to grow out of it. Celestine never saw that, because she, and only she, took pleasure in Dot’s helpless softness. Only Celestine was saddened by her daughter’s fierce progress. Day by day, Dot grew stronger. In her shopping-cart stroller she exercised to exhaustion, bouncing for hours to develop her leg muscles.'),
  ('678bfa60-5073-5db8-a7bc-f64c67774ea9', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'Which choice best describes the overall structure of the text?', '["It introduces a certain technique, mentions the hypothesis of a study into an ecological consequence of that technique, and presents evidence in support of that study’s hypothesis.", "It provides an example of a location that has adopted a particular approach, explains the methodology of a study into an ecological effect of that approach, and describes a finding of that study.", "It makes a claim about the use of a specific strategy, describes field observations of a consequence of that strategy in a particular ecosystem, and makes a supposition based on those observations.", "It presents a solution to a commonly occurring problem, summarizes the procedures used by a group of researchers studying the environmental impact of that solution, and notes the significance of the researchers’ findings."]'::jsonb, 6, 'Adelaide is one of many cities that have installed pontoons or other hardening structures to protect their shorelines against coastal hazards. To assess how birds respond to shoreline hardening and other landscape alterations, Diann Prosser et al. used a tool known as the Index of Waterbird Community Integrity to survey bird communities consisting of sixty-four species, including the tundra swan and the great blue heron, in the Chesapeake Bay on the US East Coast. The researchers concluded that shoreline hardening more negatively affects birds than does land development for uses such as housing.'),
  ('c6e4826f-c3d4-5a1a-a732-70176ebc3f67', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'Which choice best states the main idea of the text?', '["Cryptology is a field that focuses primarily on securely managing data.", "Women such as Dorothy T. Blum and Maureen Baginski have contributed to the field of cryptology.", "Dorothy T. Blum and Maureen Baginski worked together on an important project in the field of cryptology.", "Cryptology should be taught more often in schools to encourage more women to enter the field."]'::jsonb, 7, 'Women like Dorothy T. Blum made important early contributions to the history of US cryptology, a field concerned with secure data communication and storage. Blum provided cryptological services for the US Army in the 1940s and then joined the National Security Agency (NSA). She was a pioneer in transitioning the NSA to using computers for cryptoanalysis. In this way, Blum and others like her helped make it possible for more women—such as Maureen Baginski, who currently works in intelligence and supports the FBI—to enter the field of cryptology.'),
  ('4ce6315b-ca07-5be6-9ff6-ade9af2f9b1b', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'What does the text most strongly suggest about southern sea otters in environments where snails, mussels, and clams are present?', '["Those otters whose diet consists mainly of snails will likely exhibit less tooth damage than will those otters that use tools to consume mussels and clams.", "Those otters that do not use tools will likely have more robust health than those otters that do use tools.", "Those otters that do not use tools will likely need to process larger amounts of prey to meet their energy requirements than will those otters that use tools.", "Those otters that consume mussels and clams without the use of tools will likely spend less time foraging than will those otters that use tools to access the same prey resources."]'::jsonb, 8, 'Researchers who examined data from radio-tagged southern sea otters (Enhydra lutris nereis) identified fitness benefits gained by otters that used tools. By using fixed stones as anvils, tool-using otters gained access to high-quality, hard-shelled prey (e.g., mussels and clams) that they could usually not access through biting alone. Non-tool-using otters foraged abundant, energy-poor, easily extractable prey instead (e.g., snails). Even when easily processed prey were depleted, tool-using otters that processed mussels and clams were thus able to obtain their needed energy resources and to do so without incurring tooth damage.'),
  ('934a0458-3c12-5a9d-8345-701c66493221', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'Which statement, if true, would most directly support the underlined claim?', '["Besides Native Hawaiians, tens of thousands of people from other Pacific Islander communities live in Hawaibi today, including over 37,000 Samoans.", "Fewer than fifty children could speak Hawaiian when Aha Pbnana Leo was founded, but now more than 2,000 students at Aha Pbnana Leo speak it.", "Hawaiian is very similar to other languages that are spoken on the Polynesian Islands of the Pacific Ocean, including Tahitian, Samoan, and M0ori.", "Roughly 680,000 Native Hawaiian people lived in the United States in 2020, and a little less than half of them lived in Hawaibi."]'::jsonb, 9, 'Over the course of the 1900s, more and more Native Hawaiians spoke English instead of the Hawaiian language. To preserve their language, Native Hawaiian teachers founded the Aha Pbnana Leo preschool in 1984. They spoke Hawaiian while teaching, and their Native Hawaiian students were soon able to understand and speak it themselves. The school was a huge success. Eventually it opened locations around Hawaibi and started teaching Hawaiian to elementary and high school students too. <u>Thanks to</u> <u>Aha Pbnana Leo, the number of young people who speak the language has increased.</u>'),
  ('a2d59264-b0f6-5abc-b1f5-29cf19c6f665', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'Which choice most effectively uses data from the table to complete the assertion?', '["there were 16 streaky rockskippers observed at station 1.", "there were 610 streaky rockskippers observed at station 3.", "there were 16 barred flagtails observed at station 3.", "there were 50 Cocos frillgobies observed at station 1."]'::jsonb, 10, 'Cumulative Counts of Fish in Three Taiwanese Tide Pools, 1999–2018

| Species | Station 1 | Station 2 | Station 3 |
| barred flagtail | 249 | 64 | 16 |
| streaky rockskipper | 125 | 139 | 610 |
| blackspotted rockskipper | 83 | 74 | 31 |
| Cocos frillgoby | 50 | 64 | 90 |

Lin-Tai Ho and colleagues tracked fish populations in three tide pool–monitoring stations in Taiwan from 1999 to 2018. Although a total of only 31 blackspotted rockskippers were observed at station 3, that was not the lowest count at any station: _____'),
  ('1a70a585-9048-5b96-9999-ce31cdc5d040', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'Which choice best describes data from the table that support Pötzelsberger and colleagues’ conclusion?', '["Belgium reported 13 damaging fungus species but only 11 damaging insect species.", "Austria reported 51 damaging fungus species, whereas Bulgaria reported 16 damaging insect species.", "Bulgaria and Belgium reported 9 and 4 damaging fungus species, respectively, which is far fewer than Austria reported.", "Austria reported 51 damaging fungus species, which is more than either Bulgaria or Belgium reported."]'::jsonb, 11, 'Numbers of the 23 Non-native Tree Species Reported and the Insect and Fungus Threats to Them

| Country | Trees | Fungi | Insects |
| Austria | 13 | 51 | 50 |
| Belgium | 4 | 13 | 11 |
| Bulgaria | 9 | 14 | 16 |

Elisabeth Pötzelsberger and colleagues gathered data on 23 non-native tree species grown in Europe. They analyzed reports from Austria, Bulgaria, and Belgium about the number of these species grown in those countries as well as the numbers of insect and fungus species that damage those trees. The researchers concluded that Austria had a greater number of damaging fungus species than either of the other countries did.'),
  ('3a499040-ab15-5035-8a2d-2ac6764e0a46', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'Which quotation from The Wonderful Wizard of Oz most effectively illustrates the claim?', '["in Oz, “[Dorothy and her companions] passed through the rest of the forest in safety, and when they came out from its gloom saw before them a steep hill, covered from top to bottom with great pieces of rock.”", "in Oz, “Dorothy fell asleep only once, and then she dreamed she was in Kansas, where Aunt Em was telling her how glad she was to have her little girl at home again.”", "in Kansas, “Dorothy lived in the midst of the great Kansas prairies, with Uncle Henry, who was a farmer, and Aunt Em, who was the farmer’s wife.”", "in Kansas, “When Dorothy stood in the doorway and looked around, she could see nothing but the great gray prairie on every side. Not a tree nor a house broke the broad sweep of flat country.”"]'::jsonb, 12, 'The Wonderful Wizard of Oz is a 1900 novel by L. Frank Baum. In the novel, Dorothy lives in Kansas with her aunt and uncle, but she later finds herself in a land called Oz. The narrator indicates that her aunt and uncle’s house in Kansas is remote and solitary, writing that _____'),
  ('73365b94-a620-5b04-9571-2657806de188', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'Which choice most logically completes the text?', '["the evolutionary benefits of a crablike body form are less certain than many studies of carcinization had previously implied.", "despite having many living relatives, some decarcinized groups did not benefit from decarcinization.", "sideways walking may have been less important to the survival of frog crabs than a protected abdomen and other traits associated with carcinization.", "a crablike body form may not be optimal in all cases, with ecological conditions sometimes favoring the persistence of decarcinization."]'::jsonb, 13, 'Carcinization, or the evolution of a crablike body form, has taken place in crustaceans many times over the last 250 million years. Decarcinization has occurred several times as well, even though it involves the loss of traits such as sideways walking that seem to have helped carcinized groups persist in a variety of ecosystems. In a 2021 paper, Joanna Wolfe and team note that many decarcinized groups are extinct and have very few living relatives—signs that decarcinization might be an “evolutionary dead-end.” But the team also discusses frog crabs, a living decarcinized group with traits suited to dwelling in sediment; fossils show that the group had decarcinized members as far back as the Early Cretaceous. This example suggests that _____'),
  ('798b7dde-239b-542f-b66f-820424de0871', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'Which choice most logically completes the text?', '["cause other conservationists to adopt a new methodology for counting populations.", "risk making inaccurate conclusions about the effectiveness of different conservation strategies.", "benefit from including species beyond the northern muriqui.", "fail to consider less-well-known conservation approaches for the northern muriqui."]'::jsonb, 14, 'A group of primate conservationists recently began a long-term study of the effects of different conservation strategies on the northern muriqui (Brachyteles hypoxanthus). The species population is currently estimated to be around 1,000. It is challenging to accurately count these primates, however, which makes it difficult to tell whether the population is increasing, decreasing, or staying stable. The study may thus _____'),
  ('51d354d2-4d18-5881-aaff-8f69f8d271fe', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["crack, or", "crack or", "crack", "crack,"]'::jsonb, 15, 'Mountain goats were made to climb. In addition to having hard hooves that can dig into nearly any groove or _____ mountain goats have slender bodies ideal for scaling nearly ninety-degree cliffs.'),
  ('8349de1c-23d0-5f2c-b759-ab89a9bff774', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["is not", "are not", "was not", "has not been"]'::jsonb, 16, 'As an object-oriented computer programming language, Perl is used by coders like Black Girls Code founder Kimberly Bryant to create computer programs by manipulating “objects” (that is, specifically defined variables or combinations of variables) into interacting with each other. Conversely, languages like Scheme, used in software development, _____ object oriented.'),
  ('551f8560-6928-5046-9b42-f6f2db738748', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["it’s", "its", "their", "they’re"]'::jsonb, 17, 'In premodern Europe, one could sail from the east coast of England to the Netherlands or France faster than one could travel by land to England’s capital, London. In that era, historian Michael Pye argues in his 2015 book Edge of the World: A Cultural History of the North Sea and the Transformation of Europe, the North Sea did more to link the various peoples, cultures, and economies on _____ shores than to divide them.'),
  ('f30c016d-fc7a-5667-a00c-2d72329f32fd', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["these personas include specific details (demographics, browsing habits, etc.) that UX designers draw from actual users.", "specific details that UX designers draw from actual users (demographics, browsing habits, etc.) are included in these personas.", "UX designers include specific details (demographics, browsing habits, etc.) drawn from actual users in these personas.", "actual users are the source of the specific details (demographics, browsing habits, etc.) that UX designers include in these personas."]'::jsonb, 18, 'Creating personas—brief profiles of imaginary characters that represent key segments of a customer base—can help user experience (UX) designers think like and empathize with those using their products. Fictional yet realistic, _____'),
  ('e23531b9-a97a-54b0-be41-66e67236468f', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["each", "these", "it", "them"]'::jsonb, 19, 'As the exoplanet 17 Scorpii b orbits a star 408 light-years from Earth, the gas giant’s gravity causes the star to wobble. In 2020, astronomers observing the wobble—indicated by redshifts and blueshifts in the star’s spectral wavelengths—eventually attributed _____ to the gravitational influence of the previously undetected exoplanet.'),
  ('926d6aa5-1c2e-5252-8b0e-e43df9247689', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["embraced:", "embraced", "embraced,", "embraced and"]'::jsonb, 20, 'Although the term “balloonomania”—referring to the hot-air balloon fad in England and France in the late 1700s—might suggest that the public as a whole was captivated by the technology, it was not universally _____ whereas many flocked to balloon launches and purchased balloon-themed items ranging from dinnerware to accessories, others dismissed the hot-air balloon as an impractical and dangerous extravagance.'),
  ('c59fe612-3c13-59c0-8dc5-b8199b530b4e', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'Which choice completes the text with the most logical transition?', '["usually,", "for instance,", "in any case,", "in doing so,"]'::jsonb, 21, 'In February 1864, James Johnson joined the US Army. He went on to serve in the 18th New York Cavalry during the US Civil War and, _____ earned a place in US history as one of the war’s few Chinese-born American soldiers.'),
  ('e623a798-48c3-5324-87d3-68d712916fc1', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'Which choice completes the text with the most logical transition?', '["To take one well-known example,", "In accordance with this premise,", "It thus came as no surprise that,", "On the other end of the spectrum,"]'::jsonb, 22, 'The lack of accessible written sources is a common challenge faced by biographers of pre-nineteenth-century subjects. _____ when writing his biography of Alexander Hamilton (1755–1804), historian Ron Chernow had at his disposal Harold Syrett’s 26-volume, 19,000-document Papers of Alexander Hamilton.'),
  ('c4cd8a63-5de2-5bb3-83f5-963fbc97e654', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'The student wants to emphasize a difference between Judeth Insel and Ricky Quiñones. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Judeth Insel played on India Arie’s first studio album, Acoustic Soul, which was released one year before her album Voyage to India.", "Both musicians have played on India Arie albums, but Judeth Insel played viola, whereas Ricky Quiñones played guitar.", "Acoustic Soul and Voyage to India, released in 2001 and 2002, respectively, are albums by singer and songwriter India Arie.", "Judeth Insel and Ricky Quiñones have both lent their musical talents to albums by India Arie."]'::jsonb, 23, 'While researching a topic, a student has taken the following notes:

India Arie is an African American singer and songwriter.
The media outlet BBC Music has described her music as a “blend of hip hop, soul and folk [that is] as subtle as it [is] inspired.”
Her acclaimed albums feature many talented musicians.
Judeth Insel played viola on her first studio album, Acoustic Soul (2001).
Ricky Quiñones played guitar on her second studio album, Voyage to India (2002).'),
  ('40604f14-3324-508b-927b-a4b403c0ca46', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'The student wants to emphasize the order in which the supercontinents were formed. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Vaalbara and Euramerica were both supercontinents, single landmasses made up of most or all of Earth’s continents.", "The supercontinent Euramerica formed long after the supercontinent Vaalbara.", "Forming and breaking apart over hundreds of millions of years, supercontinents are made up of most or all of Earth’s continents.", "Vaalbara formed about 3.6 billion years ago but eventually broke apart."]'::jsonb, 24, 'While researching a topic, a student has taken the following notes:

A supercontinent is a single landmass made up of most or all of Earth’s continents.
Over time, continents merge together to form supercontinents, which then break apart. This process is believed to take hundreds of millions of years and is known as the supercontinent cycle.
Vaalbara was a supercontinent that formed about 3.6 billion years ago.
Euramerica was a supercontinent that formed about 300 million years ago.'),
  ('9714d537-bedc-59de-b859-f15f3c49e59e', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'The student wants to emphasize a difference between Uros Island and Golden Connection. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Grimanesa Amoros often employs LED lights in her work, but the smooth LED domes of Uros Island stand in contrast to the tangled LED tubes of Golden Connection.", "Uros Island and Golden Connection are two LED light sculptures by well-known artist Grimanesa Amoros.", "In 2011, Grimanesa Amoros debuted Uros Island, a part of her Uros series.", "Many of Grimanesa Amoros’s sculptures, like Uros Island and Golden Connection, incorporate LED lights in the form of domes or tubes."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

Grimanesa Amoros is a Peruvian American artist well known for her LED light sculptures. Uros Island (2011) is from her Uros series of works.
It is made of smooth multicolored LED domes.
Golden Connection (2013) is from her Huanchaco series of works.
It is made of entangled blue and white LED tubes.'),
  ('41505f3d-1ae1-5496-abd4-7a13e20fa172', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'The student wants to contrast dichloromethane and tetradecafluorohexane. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Dichloromethane, a hydrochlorocarbon, is composed of hydrogen, chlorine, and carbon; tetradecafluorohexane, a perfluorocarbon, is composed of fluorine and carbon.", "Dichloromethane and tetradecafluorohexane are chemical compounds used in cooling technologies; the compounds are known as refrigerants.", "The hydrochlorocarbon dichloromethane and the perfluorocarbon tetradecafluorohexane are both refrigerants that can be used in cooling technologies like air conditioners.", "Tetradecafluorohexane, a refrigerant, can be used in cooling technologies to absorb heat and release cold air."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

Refrigerants are chemical compounds used in cooling technologies, such as air conditioners. Air conditioners can use refrigerants to absorb heat and release cold air.
The refrigerant dichloromethane is a hydrochlorocarbon (HCC).
HCCs are composed of the elements hydrogen, chlorine, and carbon.
The refrigerant tetradecafluorohexane is a perfluorocarbon (PFC).
PFCs are composed of fluorine and carbon.'),
  ('c3cfea65-9457-5200-8406-325493c35848', 'c128ce21-9cd3-541e-b08f-656cb1889050', 'The student wants to explain whom the award is named for. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["In 1994, Raj Reddy won the A.M. Turing Award for pioneering the development of large-scale artificial intelligence systems.", "The A.M. Turing Award is given for “major contributions of lasting importance to computing.”", "The A.M. Turing Award is named for groundbreaking British mathematician Alan Turing.", "It was in 1994 that Raj Reddy won the A.M. Turing Award."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

The A.M. Turing Award is a prestigious award given by the Association for Computing Machinery (ACM).
The ACM gives the award for “major contributions of lasting importance to computing.” It is named after groundbreaking British mathematician Alan Turing.
Raj Reddy won the award in 1994 for pioneering the development of large-scale artificial intelligence systems.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('ae9057f7-7685-54da-9c4a-4c73f97e4a10', 0, null, '**Choice A is correct.** The sentence says that certain features of mosque architecture are present in nearly all mosques, and it gives the mihrab as an example that "almost all mosques include." The adjective "universal" precisely conveys that these features are nearly found everywhere or in all cases, matching the clause that follows.
**Choice B is incorrect.** "Elaborate" describes complexity or ornamentation, not frequency or ubiquity; it doesn’t fit the claim that the feature is included in almost all mosques.
**Choice C is incorrect.** "Illusory" means deceptive or not real, which contradicts the statement that these features actually exist in nearly all mosques.
**Choice D is incorrect.** "Idealized" refers to a perfected or stylized form and does not address how commonly the feature appears, so it doesn’t match the context.
**Faster approach:** Focus on the clause after the blank ("which almost all mosques include") to identify that the missing word must mean "found in nearly all cases"; eliminate choices that describe quality rather than ubiquity.'),
  ('281482de-ae1f-5b88-a8c5-b5c3cb1c80c7', 3, null, '**Choice D is correct.** The sentence says precise dating is impossible because the sculptures have been moved from their original context; therefore the dates that archaeologists assign must be imprecise or not exact. "Approximate" directly means close to the actual value but not exact, which exactly matches the idea that precise dates cannot be determined.
**Choice A is incorrect.** "Uncontroversial" means not disputed; the passage addresses precision of dating, not whether scholars agree, so this choice is not supported.
**Choice B is incorrect.** "Irrelevant" means not related to the matter at hand; the dates are clearly relevant to the sculptures, so this does not fit.
**Choice C is incorrect.** "Applicable" means capable of being applied; this has no bearing on the precision of the dates and does not follow from the information given.
**Faster approach:** Focus on the clause that follows ("making precise dating impossible") and choose the option that conveys lack of exactness—here, "approximate."'),
  ('9b34f9ff-8241-590d-8bfc-7d5130f7a24b', 0, null, '**Choice A is correct.** The sentence needs a noun that pairs with the following phrase "and recent empirical observations..." to form a single subject that "have led some ecologists to express reservations." "Discrepancies between traditional descriptions ... and recent empirical observations ..." correctly indicates a difference between the two items and explains why ecologists would be skeptical about the utility of the descriptions.
**Choice B is incorrect.** "Proclamations of" does not set up the parallel structure with "and recent empirical observations" and does not naturally explain why ecologists would express reservations.
**Choice C is incorrect.** "Recurrences of" implies repetition and does not fit logically with contrasting descriptions and observations or account for reservations.
**Choice D is incorrect.** "Affinities between" would suggest similarity rather than conflict; similarity would not plausibly cause ecologists to question the descriptions'' utility.
**Faster approach:** Look for a word that creates a clear contrast between the two coordinated elements ("between ... and ...")—choose the option that signals a discrepancy or conflict when the context implies skepticism.'),
  ('f5023baa-7099-5ec3-918c-9863771bf0bf', 2, null, '**Choice C is correct.** The underlined sentence gives specific examples of effects the Calamophyton trees had on the land: their roots reduced soil erosion and their shed twigs created habitats. These examples directly illustrate the claim in the preceding sentence that the forests "changed the land significantly," so the sentence’s function is to show how conditions on the land were altered.
**Choice A is incorrect.** The sentence does not make any claim about older fossilized forests or their dates; it describes effects of the forests, not their antiquity.
**Choice B is incorrect.** The sentence does not present competing views or a debate about timing; it offers concrete consequences of the forests'' presence.
**Choice D is incorrect.** The sentence says nothing about the rate or speed at which the forests spread; it addresses environmental effects instead.
**Faster approach:** Look for signal words that show purpose (here, example verbs and nouns describing effects). If a sentence lists concrete effects, choose the answer that says it illustrates or provides examples of those effects.'),
  ('759c7174-8af4-56af-b4e4-a0ca4300de52', 0, null, '**Choice A is correct.** The passage’s main purpose is to convey the narrator’s conviction that she understands Dot better than Dot’s mother, Celestine, does. The narrator explicitly asserts a "mental connection" with Dot and contrasts her own perception (that Dot "was never meant to be a baby" and is "impatient with babyhood") with Celestine’s reactions, saying Celestine "never saw that" and takes pleasure in Dot’s "helpless softness."
**Choice B is incorrect.** The passage does not speculate that Dot’s future personality will resemble Celestine''s; it contrasts current perceptions rather than predicting Dot’s later character.
**Choice C is incorrect.** The passage describes Dot exercising in her stroller, but its focus is on differing interpretations of Dot’s nature, not on activities the adults do to amuse her.
**Choice D is incorrect.** There is no comparison of physical appearances between the narrator and Celestine; the contrast is about their reactions to and understanding of Dot.
**Faster approach:** Look for the narrator’s main claim and any explicit contrasts; the sentence stating a "mental connection" and the following contrasts with Celestine immediately identify the primary purpose.'),
  ('678bfa60-5073-5db8-a7bc-f64c67774ea9', 1, null, '**Choice B is correct.** The passage starts by giving an example city (Adelaide) that has adopted shoreline hardening, then states how Prosser et al. assessed effects—using the Index of Waterbird Community Integrity to survey bird communities—and finishes by reporting the researchers’ finding that shoreline hardening more negatively affects birds than land development. This sequence matches an example, a description of methodology, and a report of results.
**Choice A is incorrect.** The passage does not primarily introduce a technique nor explicitly state a hypothesis; it gives an example location and then describes a study and its conclusion rather than framing and testing a stated hypothesis.
**Choice C is incorrect.** The passage does not frame a tentative supposition based on observations; it reports a study’s methodology and its conclusion rather than presenting field observations followed by speculation.
**Choice D is incorrect.** Although shoreline hardening is described as a protective approach, the passage does not present it as a solution to a commonly occurring problem nor emphasize the broader significance of the findings; it focuses on the study method and result instead.
**Faster approach:** Identify the passage’s sequence—example/location, method, result—and match that sequence to the answer choices; choose the option whose three-part description follows the same order.'),
  ('c6e4826f-c3d4-5a1a-a732-70176ebc3f67', 1, null, '**Choice B is correct.** The passage emphasizes that women such as Dorothy T. Blum made important early contributions to U.S. cryptology and that those contributions helped make it possible for later women—like Maureen Baginski—to enter the field. This statement captures the passage’s main idea about women’s roles and influence in cryptology.
**Choice A is incorrect.** While the passage defines cryptology as concerned with secure data communication and storage, that detail supports the context rather than stating the main idea about women’s contributions.
**Choice C is incorrect.** The passage does not say Blum and Baginski worked together on a project; it presents Blum’s early work and Baginski as a later example.
**Choice D is incorrect.** The passage does not make a recommendation about teaching cryptology in schools or argue that it should be taught more often.
**Faster approach:** Identify the repeated focus (here, women’s contributions and influence) and choose the answer that generalizes that focus rather than a detail or an unstated recommendation.'),
  ('4ce6315b-ca07-5be6-9ff6-ade9af2f9b1b', 2, null, '**Choice C is correct.** The passage states that tool-using otters access "high-quality, hard-shelled prey (e.g., mussels and clams)" while non-tool-using otters forage for "abundant, energy-poor, easily extractable prey (e.g., snails)." If snails are energy-poor, otters that rely on them would need to consume or process a larger quantity of such prey to meet the same energy requirements as otters that eat higher-energy mussels and clams, so non-tool users likely must process more prey overall.
**Choice A is incorrect.** The passage says tool-using otters can obtain energy from mussels and clams "without incurring tooth damage," so it does not support the claim that snail-eaters would have less tooth damage than tool users.
**Choice B is incorrect.** The passage provides no basis for asserting that non-tool users have more robust health; it only contrasts prey type and energy content.
**Choice D is incorrect.** The passage does not state anything about time spent foraging when consuming mussels and clams without tools versus using tools.
**Faster approach:** Identify the energy-quality contrast ("high-quality" vs "energy-poor") and translate it directly into consequences about how much prey must be processed to meet energy needs; this yields the correct choice quickly.'),
  ('934a0458-3c12-5a9d-8345-701c66493221', 1, null, '**Choice B is correct.** The underlined claim attributes an increase in the number of young Hawaiian speakers to the Aha Pbnana Leo program. Choice B gives concrete before-and-after numbers—fewer than fifty children who could speak Hawaiian at the program’s founding and now more than 2,000 students at Aha Pbnana Leo who speak it—which directly links the school’s existence to a large increase in young speakers.
**Choice A is incorrect.** It provides information about other Pacific Islander populations in Hawaibi, which does not address whether Aha Pbnana Leo caused an increase in young Hawaiian speakers.
**Choice C is incorrect.** It describes linguistic similarity between Hawaiian and other Polynesian languages but gives no evidence about changes in the number of young Hawaiian speakers or the school’s effect.
**Choice D is incorrect.** It gives overall Native Hawaiian population numbers but does not show that young people specifically increased their Hawaiian-language use because of the school.
**Faster approach:** Look for an answer that gives direct before-and-after or causal evidence linking the program to more young speakers; empirical numeric change (choice B) most directly supports such a causal claim.'),
  ('a2d59264-b0f6-5abc-b1f5-29cf19c6f665', 2, null, '**Choice C is correct.** The table shows 31 blackspotted rockskippers at station 3 and also shows 16 barred flagtails at station 3, and 16 is less than 31, so the blackspotted rockskipper total at station 3 was not the lowest count because the barred flagtail count there was lower.
**Choice A is incorrect.** The table lists 125 streaky rockskippers at station 1, not 16, so this statement is false.
**Choice B is incorrect.** Although the table does list 610 streaky rockskippers at station 3, that number is much greater than 31 and does not support the claim that 31 was not the lowest count.
**Choice D is incorrect.** The table shows 50 Cocos frillgobies at station 1, but 50 is greater than 31, so this does not demonstrate that 31 was not the lowest count.
**Faster approach:** Scan the table for any cell with a value less than 31; then eliminate answer choices that refer to larger numbers or incorrect cells. This quickly identifies the 16 in the barred flagtail row at station 3.'),
  ('1a70a585-9048-5b96-9999-ce31cdc5d040', 3, null, '**Choice D is correct.** The table shows that Austria has 51 damaging fungus species, while Bulgaria and Belgium have 14 and 13, respectively; 51 is greater than either of those numbers, directly supporting the researchers’ conclusion.
**Choice A is incorrect.** Although Belgium did report 13 fungi and 11 insects, this statement compares fungi to insects within Belgium and does not address whether Austria has more damaging fungus species than the other countries.
**Choice B is incorrect.** This choice mixes categories (Austria’s fungi vs. Bulgaria’s insects) instead of comparing fungus counts across countries, so it does not support the stated conclusion.
**Choice C is incorrect.** The numbers 9 and 4 are counts of trees, not fungus species; the fungus counts for Bulgaria and Belgium are 14 and 13, respectively, so the statement is factually wrong.
**Faster approach:** Scan the fungus column in the table and compare the three numbers; the largest fungus count identifies the country referenced in the conclusion.'),
  ('3a499040-ab15-5035-8a2d-2ac6764e0a46', 3, null, '**Choice D is correct.** The passage claims Dorothy’s house is remote and solitary, and Choice D directly supports that claim by stating that when Dorothy looked around she could “see nothing but the great gray prairie on every side” and that “Not a tree nor a house broke the broad sweep of flat country,” which explicitly conveys isolation and remoteness.
**Choice A is incorrect.** That quotation describes a rocky hill in Oz and does not address Dorothy’s home in Kansas or its solitary location.
**Choice B is incorrect.** That line describes a dream about being in Kansas and Aunt Em’s feelings, but it does not describe the physical remoteness or solitude of the house.
**Choice C is incorrect.** That sentence states who Dorothy lived with and that Uncle Henry was a farmer, but it does not convey the sense of isolation or solitude described in the claim.
**Faster approach:** For command-of-evidence items, scan each quotation for words that directly match the claim (here, words like “nothing,” “on every side,” “not a tree nor a house”) and eliminate choices that lack explicit spatial or isolating descriptions.'),
  ('73365b94-a620-5b04-9571-2657806de188', 3, null, '**Choice D is correct.** The passage notes that decarcinization often appears to be an “evolutionary dead-end” because many decarcinized groups are extinct and have few living relatives, but then gives the counterexample of frog crabs, a living decarcinized lineage that has persisted since the Early Cretaceous and has traits suited to sediment dwelling. The contrast between the general pattern and this durable exception supports the idea that a crablike body form is not always optimal and that ecological conditions can favor the long-term persistence of decarcinization.
**Choice A is incorrect.** The passage does not argue that the benefits of a crablike form are uncertain in general; it presents an exception that shows decarcinization can persist in some contexts, not that carcinization’s benefits are broadly doubtful.
**Choice B is incorrect.** The passage explicitly says many decarcinized groups are extinct and have few relatives; it does not claim those groups had many living relatives.
**Choice C is incorrect.** The passage does not compare the relative importance of sideways walking versus a protected abdomen in frog crabs; it only notes frog crabs are decarcinized and adapted for sediment dwelling.
**Faster approach:** When a passage gives a general trend and then an example that contradicts it, choose the answer that reconciles both by stating a conditional or situational conclusion (here, that ecological conditions sometimes favor the exception).'),
  ('798b7dde-239b-542f-b66f-820424de0871', 1, null, '**Choice B is correct.** The passage explains that accurately counting the northern muriqui is challenging, which makes it difficult to tell whether the population is increasing, decreasing, or staying stable. If the study cannot determine true population trends, it may therefore reach inaccurate conclusions about how effective different conservation strategies are; uncertainty in the population data directly undermines the study’s ability to evaluate strategy outcomes.
**Choice A is incorrect.** The passage gives no indication that the study’s methods will prompt other conservationists to adopt a new counting methodology; it only states that counting is challenging.
**Choice C is incorrect.** Including additional species is unrelated to the problem described, which is uncertainty about counting this species’ population.
**Choice D is incorrect.** The passage does not suggest the study will neglect less-well-known approaches; it focuses on measurement difficulties, not on the range of approaches considered.
**Faster approach:** Identify the problem stated (uncertain counts) and choose the answer that directly follows from that problem (inaccurate or uncertain conclusions), eliminating choices that introduce new, unsupported ideas.'),
  ('51d354d2-4d18-5881-aaff-8f69f8d271fe', 3, null, '**Choice D is correct.** The clause beginning with "In addition to having..." is an introductory phrase that modifies the main clause "mountain goats have slender bodies..." The phrase must be set off from the main clause with a comma, so "groove or crack," correctly signals the end of the introductory material and leads into the independent clause.
**Choice A is incorrect.** "crack, or" creates an unnecessary coordinating conjunction after the paired items "groove or crack," producing an ungrammatical continuation before the main clause.
**Choice B is incorrect.** "crack or" leaves out the necessary comma to separate the introductory phrase from the main clause, and it also adds an extra conjunction that disrupts the sentence structure.
**Choice C is incorrect.** "crack" with no comma fails to mark the boundary between the introductory phrase and the main clause, causing a run-on or misread sentence.
**Faster approach:** Identify the full introductory phrase and place a comma where it ends; if the subject and verb of the main clause follow, a comma is usually required to separate them.'),
  ('8349de1c-23d0-5f2c-b759-ab89a9bff774', 1, null, '**Choice B is correct.** The subject of the clause is "languages," which is plural, so the verb must be plural as well. "Are not" correctly matches the present-tense plural subject and conveys the intended contrast with Perl, so "languages like Scheme... are not object oriented" is grammatical and clear.
**Choice A is incorrect.** "Is not" uses a singular verb with the plural subject "languages," producing a subject-verb agreement error.
**Choice C is incorrect.** "Was not" is past tense and singular; it both disagrees in number with "languages" and shifts the time frame inappropriately.
**Choice D is incorrect.** "Has not been" is singular (or would require a plural "have not been") and creates a perfect-tense construction that changes the intended simple-contrast meaning.
**Faster approach:** Quickly identify the subject ("languages" = plural) and choose a present-tense plural verb form — eliminate any singular or past-tense options.'),
  ('551f8560-6928-5046-9b42-f6f2db738748', 1, null, '**Choice B is correct.** The sentence needs a possessive that links the shores to the body named earlier: the North Sea. The singular possessive pronoun "its" correctly indicates that these are the North Sea’s shores: "the North Sea did more to link the various peoples, cultures, and economies on its shores." This reading is clear and grammatically correct.
**Choice A is incorrect.** "it''s" is a contraction of "it is" or "it has," not a possessive, so it cannot show ownership of "shores."
**Choice C is incorrect.** "their" is a plural possessive that would imply the shores belong to the
peoples/cultures/economies rather than to the North Sea, which changes the intended meaning.
**Choice D is incorrect.** "they''re" means "they are," not possession, so it does not fit.
**Faster approach:** When faced with its/it''s/their/they''re, first eliminate contractions (it''s/they''re) unless the sentence needs "is/are." Then decide whether a singular or plural possessive is required by identifying the antecedent; choose "its" for a singular noun like "the North Sea."'),
  ('f30c016d-fc7a-5667-a00c-2d72329f32fd', 0, null, '**Choice A is correct.** The sentence begins with the introductory participial phrase "Fictional yet realistic," which must modify the noun that immediately follows the comma. Choice A places "these personas" directly after the comma, so the modifier correctly describes the personas: "Fictional yet realistic, these personas include specific details (demographics, browsing habits, etc.) that UX designers draw from actual users."
**Choice B is incorrect.** It places "specific details" immediately after the introductory phrase, incorrectly implying that the details (not the personas) are "Fictional yet realistic," which creates a misplaced modifier.
**Choice C is incorrect.** It places "UX designers" immediately after the phrase, which would illogically suggest that the designers are "Fictional yet realistic," another misplaced modifier error.
**Choice D is incorrect.** It places "actual users" after the phrase, creating the same problem by suggesting that the users—not the personas—are "Fictional yet realistic."
**Faster approach:** Recognize the introductory participial phrase and ensure the noun immediately after the comma is the thing being described; choose the option that puts "these personas" right after the comma.'),
  ('e23531b9-a97a-54b0-be41-66e67236468f', 2, null, '**Choice C is correct.** The pronoun in the blank must refer back to the singular noun "the wobble," so a singular pronoun is required. "It" is the singular, neutral pronoun that correctly stands for "the wobble" in the clause "attributed it to the gravitational influence...," which follows the standard English construction "attribute X to Y."
**Choice A is incorrect.** "Each" is distributive and cannot replace a single noun phrase like "the wobble," so it does not fit grammatically.
**Choice B is incorrect.** "These" is a plural demonstrative pronoun and does not agree in number with the singular antecedent "the wobble."
**Choice D is incorrect.** "Them" is a plural object pronoun and therefore does not agree in number with the singular "the wobble."
**Faster approach:** Identify the antecedent noun and match pronoun number; because "the wobble" is singular, immediately choose the singular pronoun "it."'),
  ('926d6aa5-1c2e-5252-8b0e-e43df9247689', 0, null, '**Choice A is correct.** The sentence requires a word that fits grammatically and contextually after "was not universally." The phrase "was not universally embraced" conveys that while many people were enthusiastic about hot-air balloons, there were also those who did not support or accept the idea. The structure of the sentence calls for a simple past participle verb, making "embraced" the ideal choice.
Now, let’s examine why each of the other options is incorrect:
**Choice B (embraced)** is incorrect because, while it is the same as Choice A, it lacks punctuation, which is necessary for the flow of the sentence.
**Choice C (embraced,)** is incorrect as it includes a comma that is unnecessary and disrupts the grammatical structure of the sentence. The sentence flows better without it.
**Choice D (embraced and)** is incorrect because the conjunction "and" suggests that there is an additional clause or phrase that follows. However, the sentence does not continue in that way, making it inappropriate in this context.'),
  ('c59fe612-3c13-59c0-8dc5-b8199b530b4e', 3, null, '**Choice D is correct.** The phrase "in doing so," appropriately signals that Johnson’s service in the 18th New York Cavalry directly led to his earning a place in U.S. history; it shows cause and effect between the two clauses. The sentence thus reads smoothly and logically: by serving, he earned that distinction.
**Choice A is incorrect.** "usually," indicates frequency and does not express the causal relationship implied by the sentence.
**Choice B is incorrect.** "for instance," introduces an example, but the second clause is not an example of his service; it is the consequence of it.
**Choice C is incorrect.** "in any case," signals concession or irrelevance and does not convey that his service produced the historical outcome.
**Faster approach:** Look for a transition that shows cause-and-effect when the second clause is the result of the first; eliminate options that signal frequency, example, or concession.'),
  ('e623a798-48c3-5324-87d3-68d712916fc1', 3, null, '**Choice D is correct.** The first sentence states a general problem (a lack of sources); the blank must introduce a contrasting situation. "On the other end of the spectrum," signals a contrast and properly sets up the example of Ron Chernow, who—unlike many biographers—had an unusually large documentary resource. The result is a coherent contrast between the general claim and this specific exception.
**Choice A is incorrect.** "To take one well-known example," could introduce an example, but it does not necessarily signal the necessary contrast; here the following clause describes a counterexample, so a contrast marker is stronger and clearer.
**Choice B is incorrect.** "In accordance with this premise," indicates agreement with the preceding statement, which would imply Chernow also lacked sources; that contradicts the rest of the sentence.
**Choice C is incorrect.** "It thus came as no surprise that," suggests that what follows was expected given the prior sentence; since the prior sentence describes a lack of sources, the abundance Chernow enjoyed would not be unsurprising, so the phrase is illogical here.
**Faster approach:** Look for whether the blank needs a contrast or a continuation; if the next clause presents an exception to the general statement, choose a contrast signal such as "on the other end of the spectrum."'),
  ('c4cd8a63-5de2-5bb3-83f5-963fbc97e654', 1, null, '**Choice B is correct.** The notes state that Judeth Insel "played viola on her first studio album, Acoustic Soul (2001)" and that Ricky Quiñones "played guitar on her second studio album, Voyage to India (2002)." Choice B directly contrasts the two musicians by naming the different instruments each played, which most effectively emphasizes a difference between them.
**Choice A is incorrect.** Although it notes the albums'' release order, it emphasizes a difference in dates between albums rather than contrasting the two musicians themselves.
**Choice C is incorrect.** This sentence simply identifies the albums and release years and does not emphasize any difference between the two musicians.
**Choice D is incorrect.** That choice highlights a similarity (both contributed) rather than emphasizing a difference.
**Faster approach:** For questions asking to emphasize a difference, scan choices for one that explicitly contrasts the two subjects (words like "whereas" or two different roles/instruments) and eliminate choices that state only dates, general facts, or similarities.'),
  ('40604f14-3324-508b-927b-a4b403c0ca46', 1, null, '**Choice B is correct.** The notes give the formation times for Vaalbara (about 3.6 billion years ago) and Euramerica (about 300 million years ago); stating that Euramerica formed long after Vaalbara accurately emphasizes the order of formation by directly comparing those dates.
**Choice A is incorrect.** Although it correctly identifies both as supercontinents, it does not indicate which formed first or otherwise emphasize their chronological order.
**Choice C is incorrect.** It describes the supercontinent cycle and composition but does not address the relative timing or order in which Vaalbara and Euramerica formed.
**Choice D is incorrect.** It notes that Vaalbara formed and broke apart but fails to mention Euramerica or compare their formation times, so it does not emphasize the order.
**Faster approach:** Directly compare the dates given; the larger (older) date indicates the earlier formation, so a choice stating "long after" signals the correct order.'),
  ('9714d537-bedc-59de-b859-f15f3c49e59e', 0, null, '**Choice A is correct.** It explicitly emphasizes a difference by contrasting the materials and forms given in the notes: "smooth LED domes" for Uros Island versus "tangled LED tubes" for Golden Connection. The sentence uses clear comparative language ("stand in contrast to") and draws directly on the specific details the student recorded.
**Choice B is incorrect.** While accurate, it merely states both works are LED sculptures by the artist and does not emphasize any difference between them.
**Choice C is incorrect.** This choice mentions only Uros Island and gives its date and series; it does not compare the two works or highlight a difference.
**Choice D is incorrect.** Although it notes that the sculptures use domes or tubes, it presents the information neutrally rather than emphasizing the contrast between the smooth domes of Uros Island and the tangled tubes of Golden Connection.
**Faster approach:** Look for an answer that uses explicit comparative or contrast language and cites the exact differing details from the notes (here, "domes" vs. "tubes" and "smooth" vs. "tangled").'),
  ('41505f3d-1ae1-5496-abd4-7a13e20fa172', 0, null, '**Choice A is correct.** It directly contrasts the two refrigerants by naming each compound and giving the distinct elemental composition of each: dichloromethane is an HCC containing hydrogen, chlorine, and carbon, while tetradecafluorohexane is a PFC containing fluorine and carbon. Those facts come exactly from the notes and show a clear difference between the two substances.
**Choice B is incorrect.** It only states a similarity (both are refrigerants used in cooling technologies) and does not contrast their differences in composition.
**Choice C is incorrect.** Like B, it emphasizes similarity—both are refrigerants—and does not highlight how they differ chemically.
**Choice D is incorrect.** It discusses only tetradecafluorohexane’s use and omits any comparison with dichloromethane, so it fails to contrast the two.
**Faster approach:** For a contrast question, look for the answer that presents differing characteristics for each item (here, different elemental compositions); eliminate choices that state only similarities or describe just one item.'),
  ('c3cfea65-9457-5200-8406-325493c35848', 2, null, '**Choice C is correct.** The notes explicitly state that the award "is named after groundbreaking British mathematician Alan Turing," which directly and succinctly explains whom the award is named for and uses only the relevant information.
**Choice A is incorrect.** Although accurate, this sentence focuses on Raj Reddy’s 1994 win and his contributions, not on whom the award is named for.
**Choice B is incorrect.** This choice describes the criteria for receiving the award, not the person for whom the award is named.
**Choice D is incorrect.** Like choice A, this repeats the fact of Raj Reddy’s win but does not identify the award’s namesake.
**Faster approach:** Scan the choices for the one that directly repeats or paraphrases the phrase "named for" from the notes; that option will answer the prompt most efficiently.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

-- PeaklyTest Aug 2025 · Reading & Writing · Module 2
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('0f790b19-6f15-547c-9661-f92a7f26e85b', 'PeaklyTest Aug 2025 · Reading & Writing · Module 2', 'Reading & Writing', 'Reading & Writing, Module 2 of the Aug 2025 PeaklyTest · 27 questions · 32 minutes', 32, 141, true, 'PeaklyTest Aug 2025 · Reading & Writing', 2)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('2df7880b-6c25-5b09-ad58-d09d0544a862', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice completes the text with the most logical and precise word or phrase?', '["dissociate from", "collude with", "compensate for", "attest to"]'::jsonb, 1, 'Studying menus from nineteenth-century restaurants, old coupons clipped out of newspapers, and posters promoting concerts by long-forgotten musicians may seem like a frivolous pursuit, but ephemeral objects like these are useful as evidence of cultural change: they can _____ shifts in norms, values, and concerns that traditional objects of historical inquiry may not.'),
  ('ad914c40-d165-5942-bd48-a92320b8806d', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice completes the text with the most logical and precise word or phrase?', '["Components", "Safeguards", "Proponents", "Epitomes"]'::jsonb, 2, 'In the architectural process called modular construction, a building is manufactured in modules under controlled conditions and then assembled at its intended location. _____ of this approach cite the production of less material waste and a faster return on investment.'),
  ('df7934c5-4e40-50f1-9ca6-7b30a11b6005', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice completes the text with the most logical and precise word or phrase?', '["attrition", "circumspection", "impartiality", "replicability"]'::jsonb, 3, 'Run by researchers in Europe, the Survey of Health, Ageing, and Retirement in Europe (SHARE) is an examination of aging that has attempted to track approximately 120,000 people for several years. Long-running studies like this need a lot of participants not merely for statistical robustness but also because of _____: over such a length of time, a substantial number of participants will withdraw or fall out of contact with the researchers.'),
  ('4b8330f4-7df6-579e-befa-20663561738e', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice completes the text with the most logical and precise word or phrase?', '["self-servingly", "sporadically", "grudgingly", "unfailingly"]'::jsonb, 4, 'Some ethicists challenge the concept of personal character, claiming that if it were meaningful, situational factors could not, as they clearly can, induce behavior contrary to that character. As Rachana Kamtekar observes, this argument is difficult to reconcile with our lay conception of character: we expect a person of helpful character to be frequently helpful, not _____ helpful.'),
  ('9b055333-249f-5248-b5f3-562fc7abe9a9', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice best describes the overall structure of the text?', '["It explains how an art exhibition differs from many other exhibitions, then analyzes the significance of that difference.", "It presents the unusual goals curators had for an art exhibition, then evaluates whether the curators achieved those goals.", "It provides an overview of an art exhibition, then explains what makes the exhibition unusual for the institution that organized it.", "It discusses the wide range of disciplines represented in an art exhibition, then explains why curators included works in those disciplines."]'::jsonb, 5, 'The Reckoning and Resilience (2022) exhibition at Duke University’s Nasher Museum of Art in Durham, North Carolina, was curated to feature the work of thirty North Carolina artists. The included artists represent a wide variety of artistic disciplines, from painters such as Juan Logan to the sculptor Stephen Hayes. In its inclusion of many borrowed works, the exhibition is atypical for the Nasher Museum, which tends to curate its exhibitions around the permanent collection of contemporary art that it owns.'),
  ('17393848-0df5-5bd7-b0f5-68de3c94b343', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice best describes the function of the underlined portion in the text as a whole?', '["To suggest that the FA is a poor point of comparison for a collection like the HM", "To emphasize the ubiquity of hand-copied collections like the FA and the HM in medieval England", "To provide context for the text’s suggestion that the HM is an outlier among collections of its time", "To illustrate how the discussion of the HM earlier in the text can improve historians’ understanding of the FA"]'::jsonb, 6, 'The Heege Manuscript (HM) is a collection of booklets of once-unbound paper sheets on which Richard Heege copied various texts at his fifteenth-century home between Derbyshire and Nottinghamshire in England. <u>Most other contemporaneous personal manuscripts like the Findern Anthology (FA) consist</u> <u>primarily of pieces by celebrated medieval authors like Hoccleve and other readings favored by elites</u>, whereas the HM has a distinctive emphasis on the popular, including entertainments like crude comedies, and the practical, with advice about manners.'),
  ('e85bba8c-c6c4-5a3f-8ea7-8bfb8e6ace7e', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice best describes a notable difference in how the speaker of Text 1 and the speaker of Text 2 portray the moon?', '["While both speakers characterize the moon as an entrapped figure, only the speaker of Text 2 describes the moon as being content with this fate.", "While both speakers present the moon as a tangible object, only the speaker of Text 1 addresses the moon’s beauty.", "While the speaker of Text 1 presents the moon as an object of play, the speaker of Text 2 presents the moon as an object of serious study.", "While the speaker of Text 1 presents the moon as seeming to be very close, the speaker of Text 2 emphasizes the moon’s distance from the speaker."]'::jsonb, 7, '**Text 1** is T.L. Hulme’s 1912 poem “Above the Dock”

**Text 2** is from Amy Lowell’s 1912 poem “The Crescent Moon.”

**Text 1**

Above the quiet dock in mid night,
Tangled in the tall mast’s corded height,
Hangs the moon. What seemed so far away
Is but a child’s balloon, forgotten after play.

**Text 2**

Slipping softly through the sky Little horned, happy moon, Can you hear me up so high? Will you come down soon?'),
  ('ccdbee36-6145-5693-b59c-87df1d6d9a41', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice best states the main idea of the text?', '["Analysis of the earliest available records of a sovereign state’s finances can be found not in the work of Hoffman and Norberg but in that of Drelichman and Voth.", "Drelichman and Voth advanced the field of research on European early modern state finance by assembling a novel collection of evidence that gave them insight into Philip II’s debt defaults.", "The research by Drelichman and Voth suggests that the logistics of ruling both Spain and much of Belgium led to short-term problems with cash that forced Philip II to default on his debts.", "Drelichman and Voth’s research on Philip II’s debt defaults builds on earlier work by Hoffman and Norberg, adding nuance to the earlier work’s findings."]'::jsonb, 8, 'Mauricio Drelichman and Hans-Joachim Voth’s research into the debt defaults of Philip II (who ruled an empire including Spain and much of Belgium from 1556 to 1598) relates to other work on European early modern state finance, including Hoffman and Norberg’s research on the relationship between state finance and political development. But Drelichman and Voth’s unique contribution to the field is their reconstruction of the earliest extant set of annual fiscal records for any sovereign state, demonstrating in turn that Philip’s defaults were caused by short-term cash shortages, not long-term unsustainable debts.'),
  ('bb8bb692-a031-51d6-9150-efce925a98b9', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice best describes what happens in the text?', '["Richard attributes Clarence’s troubles to both his own secret plotting and the distrust of Clarence that the queen and her allies Derby, Hastings, and Buckingham have planted in the king’s mind.", "Richard describes having wept as he informed Derby, Hastings, and Buckingham that the queen and her allies convinced the king to act against Clarence, and says that the earnestness of his grief caused them to accept his version of events.", "Richard acknowledges that his mischievous nature has spurred him to commit misdeeds in the past, including instigating enmity between the king and Clarence, but he reports that he has hitherto not lost the trust of the queen and her allies.", "Richard indicates that he has pretended to be aggrieved about Clarence’s situation and has proclaimed it to be the fault of the queen and her allies, but in reality, he has caused the hostility the king feels toward Clarence."]'::jsonb, 9, 'The following text is adapted from William Shakespeare’s 1597 play The Tragedy of King Richard III. Richard is reflecting on the recent arrest of his brother, the Duke of Clarence, on suspicion of treason against King Edward IV. Derby, Hastings, Buckingham, Rivers, Dorset, and Grey are also members of the English nobility.

RICHARD: I do the wrong, and first begin to brawl.
The secret mischiefs that I set [flowing]
I lay unto the grievous charge of others.
Clarence, whom I indeed have cast in darkness,
I do beweep to many simple [gullible people],
Namely, to Derby, Hastings, Buckingham;
And tell them ’tis the Queen and her allies
That stir the King against the Duke my brother.
Now they believe it, and withal whet me
To be revenged on Rivers, Dorset, Grey.'),
  ('e9341e7d-0be9-5e35-94c1-ece1d0758888', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice most effectively uses data from the table to complete the statement?', '["MSX sold approximately 4,000,000 units, whereas the Intellivision sold only approximately 3,000,000 units.", "MSX sold approximately 18,600,000 units, whereas the Intellivision sold only approximately 2,000,000 units.", "Game & Watch sold approximately 4,000,000 units, whereas the ColecoVision sold only approximately 3,000,000 units.", "Game & Watch sold approximately 18,600,000 units, whereas the ColecoVision sold only approximately 2,000,000 units."]'::jsonb, 10, 'Home Video Game Systems of the 1970s and 1980s

| System | Manufacturer | System type | Approximate number of units sold worldwide |
| ColecoVision | Coleco | console | 2,000,000 |
| Intellivision | Mattel | console | 3,000,000 |
| MSX | ASCII Corp. | computer | 4,000,000 |
| Game & Watch | Nintendo | handheld | 18,600,000 |

A student is writing a research paper on the global rise of the home video game industry during the 1970s and 1980s. The student is surprised by differences in the number of units sold by some systems compared to those sold by others. Most remarkably, the'),
  ('40b7ba08-67c8-5b8a-9789-df037a355802', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which finding, if true, would most directly weaken Schober’s hypothesis?', '["Samples of animal remains collected at Calusa sites reflect a greater diversity of marine species, particularly among sea snails, within the perimeter of watercourts than in locations known to have been devoted to the preparation and consumption of food.", "Historical population-size estimates suggest that the sea snails and fish most common in the Calusa diet were plentiful in open coastal waters when the watercourts were constructed but decreased in abundance in the years immediately after construction.", "Radar surveys of Calusa sites reveal watercourt dimensions suitable for sustaining fish of many local species but not conducive for maintaining the shallow environments with ample seagrasses that allow sea snails to thrive.", "Sediment layers excavated from Calusa watercourt sites contain heterogeneous mixtures of scales from multiple species of fish and fragments of shells from various types of sea snails, but conch shells do not constitute the majority of the mixture in most of those layers."]'::jsonb, 11, 'In what is now southern Florida, the Calusa people (circa 1000–1600 CE) supported their relatively large population’s dietary needs with hydrological engineering rather than terrestrial farming methods. They constructed watercourts (gated coastal enclosures) out of shells and sediments to trap a variety of fish as waters rose and fell with tides and seasonal sea-level shifts; watercourt pools then held the fish for later consumption. Archaeologist Theresa Schober has posited an additional purpose of these enclosures, suggesting that they were intended to foster conch. She ties this hypothesis to the high value the sea snails would have had for the Calusa, both nutritionally and as a building material (conch shells are highly durable).'),
  ('bda7ef71-2e20-5776-953f-e319d8feb881', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice best describes data from the table that support the researchers’ conclusion?', '["Whereas the total number of open flowers per growth unit peaked on day 15, the proportion of male flowers experienced a peak earlier in the flowering season, on day 10.", "Despite the sharp reduction in the total number of open flowers per growth unit from day 15 to 20, there was no decline in the estimated reproductive success rate of male flowers in that interval.", "Sex allocations were largely evenly distributed on days 10 and 15 but were female biased on days 5 and 20.", "Although sex allocations became overwhelmingly female biased by day 20, male flowers’ estimated reproductive success rate did not vary from day 5 to 20."]'::jsonb, 12, 'Observed Traits in a Population of Broadleaf Arrowhead, by Flowering Date

| Trait | Day 5 | Day 10 | Day 15 | Day 20 |
| Total number of open male and female flowers per growth unit | 25 | 65 | 110 | 45 |
| Estimated reproductive success rate of male flowers | 0.29 | 0.29 | 0.29 | 0.29 |
| Proportion of male flowers | 0.45 | 0.50 | 0.48 | 0.13 |

The mating environment hypothesis predicts that populations of flowering plants compensate for reduced mating opportunities due to dichogamy (a plant’s expression of male and female functions at separate times to prevent self-pollination) by adjusting the bias of floral sex allocation during the flowering period, increasing the probability of successful cross-plant pollination. Researchers tested the hypothesis by examining a population of broadleaf arrowhead, a plant for which bloom onset generally takes longer for male flowers than for female flowers, during the flowering season. They concluded that the mating environment hypothesis is not well supported by their observational data.'),
  ('a5ad2d0c-f4e2-5daa-94a0-7fcea11d4422', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice most logically completes the text?', '["are helpful starting points for studying computer games as art, even though these frameworks are overly simplistic.", "are useful for analyzing the narrative aspects of computer games, even if neither attempts to address player agency.", "overstate the influence of fiction and cinema on the narrative elements of computer games.", "subsume computer games under other categories of media that do not address a feature of games that is integral to player enjoyment."]'::jsonb, 13, 'Although Grant Tavinor concludes that computer games are art by virtue of their forming a subcategory of fiction, and Berys Gaut similarly places them within the realm of cinema, neither approach adequately captures a central aspect of playing these games: when the player no longer attends to the narrative and is instead simply absorbed in the instrumentalities of gameplay. This is among the reasons philosopher C. Thi Nguyen contends that the work of computer-game designers is in what he calls the medium of player agency, which the designer prescribes through rules and goals, and which elicits positive aesthetic experiences in the player who agrees to adopt it. Therefore, Nguyen’s position is that Tavinor’s and Gaut’s frameworks ______'),
  ('21878aba-6462-5a9e-8df5-2d6627f45203', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice most logically completes the text?', '["researchers ought to account for the possibility that because MPB have the capacity to compensate for reduced sunlight availability, benthic chlorophyll concentrations may not always be a reliable indicator of MPB biomass.", "although their finding was inconsistent with that of García-Robledo and Corzo, this discrepancy was not attributable to the ability of MPB to accelerate chlorophyll production to mitigate the negative impact of macroalgal accumulations.", "although elevated levels of macroalgae do not always correspond to increased levels of benthic chlorophyll, there is likely a larger trend in MPB biomass that is related to macroalgal presence but unrelated to light conditions.", "the effect of macroalgal concentrations on MPB abundance that García-Robledo and Corzo reported was not observed in Curlew Bay and other Virginia sites because low-light conditions likely are not generalizable across the sites in the studies."]'::jsonb, 14, 'As observed in a 2011 study by Emilio García-Robledo and Alfonso Corzo, macroalgal proliferation may have a suppressive effect on the abundance of cyanobacteria and other microphytobenthos (MPB)—chlorophyll-producing microbes inhabiting marine sediment—in part by reducing the amount of sunlight available to MPB. Examining benthic chlorophyll concentrations (a widely used proxy for MPB biomass) in mudflats in Curlew Bay and other coastal sites in Virginia, Alice F. Besterman and Michael L. Pace found that those concentrations did not negatively correlate with macroalgal proliferation. However, they noted that MPB may respond to low-light conditions by producing higher-than-normal concentrations of chlorophyll, and they thus concluded that _____'),
  ('f0e40d80-8de8-5435-97b6-086e816b620d', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice most logically completes the text?', '["a person who perceives certain odors as pleasant will likely perceive the odors as roughly equal in pleasantness.", "culture significantly influences whether a person perceives an odor as pleasant or unpleasant.", "personal taste has little influence on whether odors are perceived as pleasant or unpleasant.", "people agree in their perception of odors as pleasant or unpleasant regardless of where they live."]'::jsonb, 15, 'Neuroscientist Artin Arshamian and his team sought to determine what affects a person’s perception of an odor as pleasant: is it culture, personal taste, or aspects of human anatomy? The team assessed odor preferences in ten groups of people with different modes of living (urban, agricultural, and hunter-gatherer) including the Maniq people from a small community in Thailand and the Seri people from a small community in Mexico. The team observed that across cultures, people generally rated odors about the same: ethyl butyrate, which smells like peaches, was typically rated more pleasant than diethyl disulfide, which smells like garlic. The team’s study thus undermined the idea that'),
  ('8077b5bf-1fde-5f10-9a1b-dcbd1b02cc36', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice most logically completes the text?', '["levels of dissolved organic carbon and mercury are both much higher in bodies of fresh water impacted by wastewater than they are in bodies of fresh water disturbed by urban development.", "Guédron, Tisserand, and colleagues’ study used different methods to measure the concentration of mercury in fresh water than Tjerngren and colleagues’ study did.", "the effects of wastewater on the association between levels of dissolved organic carbon and mercury should not be taken as indicative of the effects of every type of human disturbance.", "disturbances linked to wastewater affect significantly more bodies of fresh water than disturbances linked to urban development do."]'::jsonb, 16, 'Many studies have found a positive association between levels of dissolved organic carbon and mercury in bodies of fresh water undisturbed by human activity. But Stéphane Guédron, Delphine Tisserand, and colleagues did not find this correlation in an examination of freshwater bodies impacted by wastewater, leading some scientists to hypothesize that the association could be particular to undisturbed waters. However, Ida Tjerngren and colleagues carried out a study on freshwater bodies disturbed by urban development that showed similar results to the studies on undisturbed waters, suggesting that _____'),
  ('f9fcc92b-e208-5ecb-adb3-1086c2cd3fc3', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["day by", "day; by", "day. By", "day by,"]'::jsonb, 17, 'Branching in Jurisprudential Schools is one of the hundreds of thousands of manuscripts that have survived from roughly the sixteenth century to the present _____ being passed down through private libraries in the city of Timbuktu, Mali. Many of these manuscripts can be found at the Al-Wangari Manuscript Library.'),
  ('dcaaf7bb-1f48-5f56-89b1-983a24a92992', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Landscape,", "Landscape:", "Landscape—", "Landscape"]'::jsonb, 18, 'The terms included in Barry Lopez and Debra Gwartney’s Home Ground: A Guide to the American _____ such as “karst,” which refers to limestone terrain riddled with caves or sinkholes—illustrate the rich vocabulary used to describe the landforms of North America.'),
  ('b6debea5-a25c-5b57-a1eb-2403d58a979b', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["and, crossed", "and had crossed", "and crossed", "and, crossing"]'::jsonb, 19, 'Following the formation of the European Union (EU) that same year, the organizers of the 1992 Tour de France wanted the bike race to reflect the cross-national flow of people and trade that the EU had made possible. The resulting course was 2,500 miles long _____ seven separate borders of neighboring countries, modeled a vision of the EU’s unifying aims.'),
  ('29f9e8f3-fb06-5574-a377-7c6ded42fb92', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["information, has generated", "information generates", "information, generating", "information generated"]'::jsonb, 20, 'As part of his I GOT UP series, Japanese conceptual artist On Kawara spent over a decade—with near daily consistency—mailing postcards to friends declaring what time he got up each day, resulting in pieces such as I Got Up at 7.19 A.M., Jun 6 1977. Such meticulous documentation of mundane _____ artworks that “resonate with existential, psychological and scientific implications about the time-space continuum,” according to the New York Times, became Kawara’s life’s work.'),
  ('84007263-c943-5912-8c7a-294812cfb072', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["protest a decision that,", "protest. A decision that", "protest; a decision that,", "protest, a decision that,"]'::jsonb, 21, 'For her film I Am Somebody (1970), a documentary about a successful months-long strike held by Black female hospital workers in Charleston, South Carolina, director Madeline Anderson chose a narrator who had participated in the _____ by allowing the narrative to be shaped by one of their own, amplified the agency and power the workers possessed.'),
  ('3ec17e65-0ce8-5464-9e53-6c36f2c12f72', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice completes the text with the most logical transition?', '["In this way,", "For instance,", "Later,", "On the other hand,"]'::jsonb, 22, 'At a time when many women writers used male pseudonyms to gain greater freedom of self-expression by evading gender conventions, Katherine Bradley and Edith Cooper adapted the practice by publishing poetry, prose, and drama for four decades under the shared name Michael Field. _____ the duo was able to express the joint creative vision that sustained their long personal and professional partnership.'),
  ('4bb96d53-e256-5940-a12b-833ce8ff0131', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice completes the text with the most logical transition?', '["Instead,", "All the same,", "Therefore,", "Specifically,"]'::jsonb, 23, 'In a 2005 study by Mellado et al., the researchers’ aim was to analyze the diet composition of cattle in Coahuila, Mexico. _____ they aimed to analyze the ratio of three different plant subtypes within these animals’ diet: graminoids, forbs, and browse.'),
  ('25a8006c-673e-5d3e-8504-86507093c37c', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice completes the text with the most logical transition?', '["Conversely,", "In addition,", "However,", "Indeed,"]'::jsonb, 24, 'John Quincy Adams employed the pseudonym “Marcellus”—a reference to a leader of an ancient Roman army—in political essays he wrote in 1793, a choice that accomplished far more than simply concealing his authorship. _____ it wasn’t an arbitrary pen name but rather a complex rhetorical strategy through which Adams aligned his political views with the venerated republican ideals of the ancient world, thereby bolstering the authority of his writing.'),
  ('51c1acff-31a3-58eb-9f29-21f5b078870a', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'The student wants to refute a claim that apricots are a better source of vitamin C than kale is. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Kale contains vitamin C (also known as ascorbic acid); in fact, there is 120 mg of vitamin C in every 100 g of kale.", "Kale contains ascorbic acid (also known as vitamin C), and apricots do too.", "Humans cannot make ascorbic acid in their bodies, but they can get it from kale and apricots.", "With 120 mg of vitamin C per every 100 g, kale is actually a better source of vitamin C than apricots, which contain only 10 mg per every 100 g."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

Kale is a vegetable that contains ascorbic acid, an essential nutrient for humans.
Apricots are fruits that contain ascorbic acid.
There is 120 milligrams (mg) of ascorbic acid per every 100 grams (g) of kale.
There is 10 mg of ascorbic acid per every 100 g of apricot.
Humans cannot make ascorbic acid in their bodies, so they must get it from foods, including fruits and vegetables.
Ascorbic acid is also known as vitamin C.'),
  ('ec8b46a8-997a-5ffc-b75f-2817d1cb767f', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'Which choice most effectively uses information from the given sentences to provide an example of a SNOTEL site?', '["The data collected by SNOTEL sites can help researchers predict downstream water supplies.", "The SNOTEL site at Bear Trap Meadow is one of around 90 automated snow measurement stations in Wyoming.", "Snow hydrologist Julie Koeberle helps maintain automated snow monitoring stations known as SNOTEL sites.", "Located throughout Wyoming, SNOTEL sites monitor snow conditions."]'::jsonb, 26, 'Snow hydrologist Julie Koeberle helps maintain automated snow measurement stations. They are called SNOTEL sites.
There are around 90 stations throughout Wyoming.
One is at Bear Trap Meadow.
The data collected can help researchers make downstream water supply predictions.'),
  ('56936cf7-c8d1-567e-b4eb-c141ccdb6dcd', '0f790b19-6f15-547c-9661-f92a7f26e85b', 'The student wants to explain why nautical miles are used to measure distances in seafaring navigation. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Nautical miles are a measure of distance equal to one minute of latitude, which is a feature nautical charts use to calculate distances and positions.", "Nautical charts use latitude and longitude to measure long distances; these charts are more accurate than flat maps for measuring distances in seafaring navigation because they account for Earth’s curvature.", "Since they directly correlate to the coordinates on nautical charts, which take into account Earth’s curvature, nautical miles are an efficient way to calculate distances at sea.", "Using nautical miles for navigation at sea takes Earth’s curvature into account, whereas measuring distances with latitude and longitude coordinates does not."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

The nautical mile (6,076 feet) is the measure of distance used in seafaring navigation. A nautical mile directly correlates to one minute (1/60th of a degree) of latitude.
The curvature of Earth affects the accurate measurement of long distances when using flat maps. Measuring distances with latitude and longitude coordinates takes into account Earth’s curvature. Mariners use nautical charts marked with latitude and longitude to quickly calculate distances and positions.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('2df7880b-6c25-5b09-ad58-d09d0544a862', 3, null, '**Choice D is correct.** The sentence says these ephemeral objects "are useful as evidence of cultural change," so the missing phrase should mean "provide evidence of" or "point to" shifts. "Attest to" precisely means to serve as evidence of or bear witness to something, making it the most logical and precise choice.
**Choice A is incorrect.** "Dissociate from" means to separate or disconnect from, which contradicts the idea that the objects serve as evidence of cultural change.
**Choice B is incorrect.** "Collude with" implies secret cooperation or conspiracy and makes no sense in the context of inanimate historical objects indicating change.
**Choice C is incorrect.** "Compensate for" means to make up for something lacking; it does not convey the idea of serving as evidence or demonstrating shifts in norms and values.
**Faster approach:** Look for a verb phrase that matches "serve as evidence of"—eliminate options that mean separation, cooperation, or making up for, leaving "attest to."'),
  ('ad914c40-d165-5942-bd48-a92320b8806d', 2, null, '**Choice C is correct.** The sentence requires a noun referring to people who make claims about modular construction; "proponents" means supporters who would cite benefits like less waste and faster return on investment. It fits both the grammar (plural noun that can "cite") and the logical content.
**Choice A is incorrect.** "Components" refers to parts of a system, not people who would cite advantages, so it does not fit the verb "cite" or the intended meaning.
**Choice B is incorrect.** "Safeguards" names protective measures or policies, which cannot "cite" benefits; the word does not refer to people and is therefore ungrammatical here.
**Choice D is incorrect.** "Epitomes" means perfect examples; while a noun, it does not refer to people who would make claims, and it does not logically fit the idea of citing advantages.
**Faster approach:** Identify whether the blank calls for a person/group (can "cite") or an object; eliminate choices that are nonhuman or irrelevant and pick the word meaning "supporters."'),
  ('df7934c5-4e40-50f1-9ca6-7b30a11b6005', 0, null, '**Choice A is correct.** The sentence contrasts a reason for needing many participants ‘‘not merely for statistical robustness but also because of _____: over such a length of time, a substantial number of participants will withdraw or fall out of contact.’’ The parenthetical clause defines the needed word as the loss of participants over time; "attrition" precisely means the gradual loss of members from a study. Thus it fits both meaning and register.
**Choice B is incorrect.** "Circumspection" means caution or prudence, which does not match the explanation about participants withdrawing or losing contact.
**Choice C is incorrect.** "Impartiality" refers to fairness or lack of bias; nothing in the sentence suggests that fairness is the reason for large sample sizes.
**Choice D is incorrect.** "Replicability" refers to the ability to reproduce results; the sentence’s parenthetical clause concerns loss of participants, not reproducibility.
**Faster approach:** Look for the phrase after the colon — it defines the needed word. Match that definition to the choice (here, "attrition" = loss of participants).'),
  ('4b8330f4-7df6-579e-befa-20663561738e', 3, null, '**Choice D is correct.** The sentence contrasts what we reasonably expect of someone with a helpful character: we expect them to be helpful often, but not necessarily always. The adverb "unfailingly" means "without fail" or "always," so saying "not unfailingly helpful" precisely conveys that helpfulness is frequent but not absolute, which matches the point about situational factors sometimes producing contrary behavior.
**Choice B is incorrect.** "Sporadically" means "occasionally" or "infrequently," but the sentence is asserting we expect helpful people to be frequently helpful, so contrasting with "sporadically" would be redundant and opposite to the intended nuance that they need not be perfect.
**Choice A is incorrect.** "Self-servingly" describes motivation (for one’s own benefit), not the frequency or consistency of helpful behavior, so it doesn’t fit the contrast set up by "frequently."
**Choice C is incorrect.** "Grudgingly" refers to the manner or attitude (reluctantly) rather than to how often someone is helpful; the sentence is about frequency/consistency, so this choice is not a precise fit.
**Faster approach:** Identify the aspect being contrasted (here, frequency/consistency expressed by "frequently") and select the answer that logically opposes that aspect (an adverb meaning "always" vs. "not always"). This structural-elimination method works for Words in Context items that hinge on specific semantic contrasts.'),
  ('9b055333-249f-5248-b5f3-562fc7abe9a9', 2, null, '**Choice C is correct.** The passage first gives an overview of the Reckoning and Resilience exhibition (curated to feature thirty North Carolina artists and listing different artists and disciplines) and then immediately explains what makes the exhibition unusual for the Nasher Museum: its use of many borrowed works rather than drawing primarily on the museum’s permanent collection. The second sentence functions as description and the final sentence provides the atypical-institutional context.
**Choice A is incorrect.** The passage does not analyze the significance of the difference; it only states that inclusion of borrowed works makes the exhibition atypical, not why that difference matters.
**Choice B is incorrect.** The passage does not present specific curatorial goals nor evaluate whether those goals were achieved; it simply describes the exhibition and notes how it differs from typical Nasher practice.
**Choice D is incorrect.** Although the passage notes a range of disciplines, it does not explain why curators included works from those disciplines; the focus is on the exhibition’s composition and its atypical borrowing practice.
**Faster approach:** Identify the opening descriptive sentences (what the exhibition is) and the final explanatory sentence (how it differs from the museum’s usual practice) to match overview + institutional contrast quickly.'),
  ('17393848-0df5-5bd7-b0f5-68de3c94b343', 2, null, '**Choice C is correct.** The underlined sentence describes what most other contemporaneous personal manuscripts contain (works by celebrated authors and readings favored by elites), which sets up a contrast with the HM’s “distinctive emphasis on the popular” and practical material; that context supports the claim that the HM is an outlier among collections of its time.
**Choice A is incorrect.** The sentence does not argue that the FA is a poor comparison; it simply characterizes the typical content of similar manuscripts to establish a baseline for comparison.
**Choice B is incorrect.** The sentence does not emphasize ubiquity or frequency of such collections overall; it specifies their typical content rather than claiming they were everywhere.
**Choice D is incorrect.** The sentence does not suggest that studying the HM will improve understanding of the FA; it only contrasts the FA’s content with the HM’s to show the HM’s distinctiveness.
**Faster approach:** Look for contrast words and structure (here, the contrast between “Most other… like the Findern Anthology” and the HM’s different emphasis); passages that set up a contrast usually function to show that one item is typical and the other is an outlier.'),
  ('e85bba8c-c6c4-5a3f-8ea7-8bfb8e6ace7e', 3, null, '**Choice D is correct.** In Text 1 the moon is described as hanging "Above the quiet dock" and as "but a child’s balloon, forgotten after play," language that makes the moon seem near and even within reach. In Text 2 the speaker calls the moon "up so high" and asks "Can you hear me up so high? Will you come down soon?" —wording that emphasizes separation and distance. The contrast in spatial language makes D the best description.
**Choice A is incorrect.** Only Text 1 conveys an entrapped or snagged moon ("tangled in the tall mast’s corded height"); Text 2 calls the moon "slipping softly," not entrapped, so the premise that both characterize it as entrapped is wrong.
**Choice B is incorrect.** Both poems treat the moon as a concrete image, but neither focuses on calling it explicitly "beautiful," so the claim about beauty is unsupported.
**Choice C is incorrect.** While Text 1 likens the moon to a child’s plaything, Text 2 does not present the moon as an object of "serious study"—it is addressed playfully and longingly, not analytically.
**Faster approach:** Compare key spatial words in each text (e.g., "hangs," "balloon" vs. "up so high"). For moon/location questions, focusing on proximity wording quickly distinguishes the speakers'' perspectives.'),
  ('ccdbee36-6145-5693-b59c-87df1d6d9a41', 1, null, '**Choice B is correct.** The passage emphasizes that Drelichman and Voth "unique contribution" was reconstructing the earliest annual fiscal records and that this reconstruction allowed them to show Philip II’s defaults were caused by short-term cash shortages rather than long-term debt—this precisely matches choice B’s claim that they advanced the field by assembling novel evidence that gave insight into his debt defaults.
**Choice A is incorrect.** It misrepresents the passage’s relationship between the researchers: the passage says Drelichman and Voth’s work "relates to" Hoffman and Norberg, not that analysis of records is found only in Drelichman and Voth rather than Hoffman and Norberg.
**Choice C is incorrect.** The passage attributes defaults to short-term cash shortages but does not claim they resulted from the logistics of ruling Spain and Belgium; that causal detail is not in the text.
**Choice D is incorrect.** Although the passage notes a relation to Hoffman and Norberg, its main point highlights Drelichman and Voth’s specific reconstruction and its substantive finding about short-term shortages—stronger than merely "adding nuance."
**Faster approach:** Locate the sentence that states the authors’ "unique contribution" or main finding and use it as the passage’s thesis; match answer choices to that precise wording to eliminate distractors quickly.'),
  ('bb8bb692-a031-51d6-9150-efce925a98b9', 3, null, '**Choice D is correct.** In the passage Richard admits that he set the secret mischiefs and has "cast" Clarence into danger, then says he "do beweep" (pretends to lament) to gullible nobles and blames the queen and her allies for stirring the king against Clarence. Thus he portrays himself as feigning grief and shifting blame while in truth he created the hostility the king feels toward his brother.
**Choice A is incorrect.** It reverses the relationship: Richard does not attribute Clarence’s troubles to both his plotting and the queen’s manipulations; he actually blames the queen publicly while privately admitting his own plotting.
**Choice B is incorrect.** While Richard says he weeps and the nobles believe him, this choice omits that Richard himself caused the hostility and frames the queen as genuinely convincing the king, which contradicts the speaker’s confession.
**Choice C is incorrect.** Richard does not claim to retain the queen’s trust; he explicitly says he has set mischiefs and is falsely blaming others, not that he has maintained any trust with the queen and her allies.
**Faster approach:** Look for the speaker’s admission phrases ("I do the wrong," "secret mischiefs that I set") to identify who is responsible, then match that to the choice that says he caused the hostility while pretending it came from others.'),
  ('e9341e7d-0be9-5e35-94c1-ece1d0758888', 3, null, '**Choice D is correct.** The table shows that Game & Watch sold approximately $18,600,000$ units and ColecoVision sold approximately $2,000,000$ units, so the contrast in units sold described in choice D accurately reflects the data and highlights the most remarkable difference.
**Choice A is incorrect.** Although the numbers for MSX ($4,000,000$) and Intellivision ($3,000,000$) are accurate, the difference between them is small compared with the large disparity the prompt calls "most remarkable."
**Choice B is incorrect.** Those figures are mismatched: MSX did not sell $18,600,000$ units, and Intellivision did not sell $2,000,000$ units according to the table.
**Choice C is incorrect.** Game & Watch sold $18,600,000$, not $4,000,000$, and ColecoVision sold $2,000,000$, not $3,000,000$, so the numbers are wrong.
**Faster approach:** Scan the table for the largest numerical difference (highest vs. lowest units sold) to find the most striking contrast quickly.'),
  ('40b7ba08-67c8-5b8a-9789-df037a355802', 2, null, '**Choice C is correct.** If radar surveys show that watercourt dimensions could not sustain the shallow, seagrass-rich environments sea snails need, then the enclosures would have been physically unsuitable for fostering conch, directly undermining Schober’s claim that they were intended for that purpose.
**Choice A is incorrect.** Finding greater diversity of sea snails inside watercourts than at food-preparation sites would support (not weaken) the hypothesis that the enclosures fostered snails.
**Choice B is incorrect.** That sea snails were plentiful in open waters when the courts were built and declined afterward could be interpreted in multiple ways (e.g., overharvesting, later environmental change) and does not directly show the enclosures were not meant to foster conch.
**Choice D is incorrect.** A heterogeneous mix with conch shells not constituting a majority suggests conch were not dominant but does not directly prove the enclosures were unsuitable for fostering them; they might still have been intended to promote conch alongside other species.
**Faster approach:** Eliminate choices that are consistent with the hypothesis (supportive or ambiguous) and select the option that presents a direct physical or causal incompatibility with the proposed purpose.'),
  ('bda7ef71-2e20-5776-953f-e319d8feb881', 3, null, '**Choice D is correct.** The table shows that by day 20 the proportion of male flowers is 0.13 (i.e., the population is overwhelmingly female biased), while the estimated reproductive success rate of male flowers remains constant at 0.29 on every day. That combination — a large shift in sex allocation by day 20 with no change in male reproductive success — supports the researchers’ conclusion that the mating environment hypothesis is not well supported by these observations.
**Choice A is incorrect.** While the total number of flowers does peak on day 15 and the proportion of male flowers is highest on day 10 (0.50), this statement describes timing but does not directly address whether sex-allocation changes affected reproductive success, which is key to the conclusion.
**Choice B is incorrect.** It is true that total flowers decline from 110 to 45 between days 15 and 20 and male success stays at 0.29, but the mating-environment prediction concerns compensatory changes in sex allocation to affect cross-pollination success; B emphasizes flower counts rather than the relevant sex-allocation versus success relationship.
**Choice C is incorrect.** The table shows day 5 is slightly female biased (0.45 male) and days 10 and 15 are near even (0.50 and 0.48), but day 20 is strongly female biased (0.13 male) — the choice’s wording "female biased on days 5 and 20" is imprecise and also does not link to reproductive success, which is central to the researchers’ conclusion.
**Faster approach:** Scan the table for any variable that is constant across days (male success = 0.29). Then find answer choices that note a change in sex allocation or flower numbers paired with that constant success — those will best support the conclusion that the hypothesis is not supported.'),
  ('a5ad2d0c-f4e2-5daa-94a0-7fcea11d4422', 3, null, '**Choice D is correct.** The passage says Tavinor and Gaut place computer games within fiction and cinema, but "neither approach adequately captures" the crucial feature that players can be absorbed in gameplay rather than narrative. Nguyen argues designers work in the "medium of player agency," a feature eliciting aesthetic experience through rules and goals. Thus Nguyen’s position is that the other frameworks subsume games under different media and fail to address this central feature of games that is integral to player enjoyment, which is exactly what choice D states.
**Choice A is incorrect.** The passage does not describe Tavinor’s and Gaut’s views as merely "helpful starting points" or "overly simplistic"; it emphasizes a specific shortcoming: failure to account for player agency.
**Choice B is incorrect.** Although B mentions narrative analysis, the passage focuses on the omission of player agency, not simply that they do not "attempt" to address it.
**Choice C is incorrect.** The passage does not claim that Tavinor and Gaut overstate the influence of fiction or cinema on narrative elements, but that those frameworks miss the non-narrative, agentive aspect of games.
**Faster approach:** Look for wording that references the passage’s key term—"player agency"—and eliminate choices that ignore that central concept; the correct choice will say the other frameworks fail to address that feature.'),
  ('21878aba-6462-5a9e-8df5-2d6627f45203', 0, null, '**Choice A is correct.** Besterman and Pace observed no negative correlation between macroalgal proliferation and benthic chlorophyll, but they also noted that MPB can up-regulate chlorophyll production under low-light conditions. That observation explains how MPB biomass could be reduced by shading while measured chlorophyll stays the same or increases, so the authors would reasonably conclude that benthic chlorophyll may not reliably indicate MPB biomass unless researchers account for such compensatory chlorophyll production.
**Choice B is incorrect.** It asserts the discrepancy was not attributable to MPB compensation, directly contradicting the authors'' stated possibility that increased chlorophyll production could mask reductions in biomass.
**Choice C is incorrect.** It posits a larger trend linking biomass to macroalgae unrelated to light, which is unsupported by the passage and ignores the authors'' focus on light-driven chlorophyll compensation.
**Choice D is incorrect.** It claims low-light conditions are not generalizable across sites as the reason for the discrepancy, but the passage emphasizes MPB’s compensatory chlorophyll response rather than lack of low-light conditions.
**Faster approach:** Look for the clause that connects the authors’ observational finding (no negative correlation) with their offered explanation (compensatory chlorophyll production); choose the answer that links those two ideas—this elimination quickly identifies A.'),
  ('f0e40d80-8de8-5435-97b6-086e816b620d', 1, null, '**Choice B is correct.** The passage reports that across diverse cultural groups people generally rated the same odors similarly (for example, ethyl butyrate was rated more pleasant than diethyl disulfide). That finding contradicts the idea that culture is a major determinant of whether an odor is perceived as pleasant or unpleasant, so the study undermines the claim that culture significantly influences odor pleasantness.
**Choice A is incorrect.** The choice is self-contradictory and unrelated: the passage does not claim that different odors are perceived as roughly equal in pleasantness by the same person.
**Choice C is incorrect.** The study’s finding about cross-cultural agreement does not directly rule out personal taste; the passage compares groups, not individual variability.
**Choice D is incorrect.** That choice restates the study’s observation rather than stating what the study undermines; the passage uses that observation to challenge the opposing idea (about culture), not to assert an unquestioned universal truth.
**Faster approach:** Identify the study’s main result, then pick the choice that the result would refute—here, cross-cultural agreement contradicts a cultural-influence claim.'),
  ('8077b5bf-1fde-5f10-9a1b-dcbd1b02cc36', 2, null, '**Choice C is correct.** The passage reports that Guédron, Tisserand, and colleagues failed to find the positive association in wastewater-impacted waters, prompting the hypothesis that the association might be limited to undisturbed waters. Tjerngren and colleagues then found results in urban-disturbed waters that matched the undisturbed-water studies, which undermines the idea that all human disturbances eliminate the association. Therefore the sensible conclusion is that wastewater effects should not be taken as representative of every kind of human disturbance.
**Choice A is incorrect.** Nothing in the passage compares absolute concentration levels between wastewater-impacted and urban-disturbed waters; it only discusses the presence or absence of an association.
**Choice B is incorrect.** The passage gives no indication that methodological differences explain the conflicting results; it instead presents an alternative explanation based on types of disturbance.
**Choice D is incorrect.** The passage offers no evidence about how many bodies of water are affected by wastewater versus urban development, so this claim is unsupported.
**Faster approach:** When a new study contradicts a proposed generalization, look for the answer that says the contradictory case doesn’t justify broad conclusions — eliminate choices that introduce unsupported details (methods, counts, magnitudes).'),
  ('f9fcc92b-e208-5ecb-adb3-1086c2cd3fc3', 0, null, '**Choice A is correct.** The sentence needs the phrase "day by" to form "to the present day by being passed down...," which correctly links the time frame to the method by which the manuscripts survived. "day by" supplies the necessary preposition "by" to introduce the participial phrase "being passed down," creating a grammatically complete and clear sentence.
**Choice B is incorrect.** A semicolon before "by" would separate closely related elements improperly; the clause following a semicolon must be independent, but "by being passed down..." is not an independent clause.
**Choice C is incorrect.** A period before "By" would create a sentence fragment: "By being passed down through private libraries..." cannot stand alone as a complete sentence.
**Choice D is incorrect.** The comma after "by" yields the ungrammatical sequence "day by, being..." and misplaces punctuation; the prepositional phrase should directly connect without that comma.
**Faster approach:** Identify whether the following phrase is an independent clause; if not, use the preposition that introduces the subordinate phrase. That eliminates options with periods or semicolons and leaves the simple prepositional insertion.'),
  ('dcaaf7bb-1f48-5f56-89b1-983a24a92992', 2, null, '**Choice C is correct.** The phrase such as ''karst,'' which refers to limestone terrain riddled with caves or sinkholes is an interrupting, nonrestrictive element that separates the subject from the verb. The sentence already provides a closing em dash after sinkholes—so to enclose the interruption it needs a matching opening em dash after Landscape, yielding: Landscape—such as ''karst,'' ...—illustrate. That pair of em dashes correctly isolates the parenthetical while preserving the main clause.
**Choice A is incorrect.** A comma could set off a nonrestrictive phrase, but it would not match the closing em dash and would create inconsistent, incorrect punctuation.
**Choice B is incorrect.** A colon introduces an explanation or list and cannot serve as the opening punctuation for a parenthetical that is closed with an em dash.
**Choice D is incorrect.** No punctuation leaves the interrupting such as phrase unmarked and leaves the closing em dash unmatched, making the sentence ungrammatical.
**Faster approach:** Match punctuation marks that set off interruptions: if you see a closing dash later in the sentence, choose an opening dash here; otherwise set off nonrestrictive phrases with commas.'),
  ('b6debea5-a25c-5b57-a1eb-2403d58a979b', 3, null, '**Choice D is correct.** The sentence needs a participial phrase that modifies "the resulting course" and occurs after the noun it describes. "and, crossing seven separate borders of neighboring countries," correctly presents "crossing" as a present participle describing what the course did while preserving parallel flow with the preceding clause. The comma before the participial phrase signals that it adds descriptive information about the course, and "crossing" is the correct verb form to show simultaneous action.
**Choice A is incorrect.** "and, crossed" uses the past-tense verb "crossed" after a comma, which makes it read as a separate past action rather than a descriptive participial phrase. It also creates a tense/structure mismatch with the rest of the sentence.
**Choice B is incorrect.** "and had crossed" uses past perfect, which implies an action completed before another past action; the sentence does not set up a sequence requiring past perfect and it disrupts the intended modifier function.
**Choice C is incorrect.** "and crossed" lacks the comma and uses a simple past form that makes the phrase feel like a separate coordinated verb rather than an adjectival participial phrase modifying "course." The best wording uses the participle "crossing" with a comma.
**Faster approach:** For sentences that add descriptive information about a noun after the noun, look for a participial phrase (verb+ing) set off by a comma; if the phrase describes the noun rather than adding a separate action, choose the -ing form with a comma.'),
  ('29f9e8f3-fb06-5574-a377-7c6ded42fb92', 2, null, '**Choice C is correct.** The sentence needs a participial phrase that modifies "documentation" and links naturally to the main verb "became." "Such meticulous documentation of mundane information, generating artworks that ‘resonate with...,’ became Kawara’s life’s work." The participle "generating" correctly indicates that the documentation produced the artworks, and the commas set off the modifying phrase appropriately.
**Choice A is incorrect.** "information, has generated" produces an ungrammatical clause: the comma plus finite verb "has generated" creates a sentence fragment and disrupts the main clause.
**Choice B is incorrect.** "information generates" inserts a finite verb before the main verb "became," creating a run-on and breaking the sentence’s intended structure.
**Choice D is incorrect.** "information generated" yields a past-tense verb phrase that clashes with the main clause, producing an awkward, ungrammatical sentence.
**Faster approach:** Spot whether the blank must be followed by a modifier or a verb; if the main clause already has a past-tense main verb ("became"), choose a nonfinite modifier (a participle like "generating") to avoid creating an extra finite verb.'),
  ('84007263-c943-5912-8c7a-294812cfb072', 3, null, '**Choice D is correct.** The clause "a decision that, by allowing the narrative to be shaped by one of their own, amplified the agency and power the workers possessed" is a nonessential explanatory phrase that renames or comments on the preceding idea. It must be set off by commas. "protest, a decision that," correctly connects the participial clause "who had participated in the protest" to the appositive explanatory phrase that follows, and the internal commas set off the parenthetical "by allowing..."
**Choice A is incorrect.** "protest a decision that," lacks the comma needed to set off the explanatory phrase and creates a run-on structure.
**Choice B is incorrect.** The period creates a sentence break and leaves "A decision that..." as a sentence fragment.
**Choice C is incorrect.** A semicolon must join two independent clauses; "a decision that," is not an independent clause, so the semicolon is inappropriate.
**Faster approach:** Identify whether the following phrase is an independent clause or an
appositive/explanatory phrase; if it renames or explains, use commas (not a period or semicolon) to set it off.'),
  ('3ec17e65-0ce8-5464-9e53-6c36f2c12f72', 0, null, '**Choice A is correct.** The preceding clause explains how Bradley and Cooper published under a shared name; "In this way," correctly signals that what follows is the result or consequence of that practice — that the duo was able to express a joint creative vision. The transition creates a logical causal link between the action and its outcome.
**Choice B is incorrect.** "For instance," would introduce an example, but the sentence that follows states a consequence rather than providing a specific example of the practice.
**Choice C is incorrect.** "Later," indicates a sequence in time, but the sentence describes an effect of publishing under a shared name, not a later event.
**Choice D is incorrect.** "On the other hand," signals contrast with a previous idea, but nothing in the passage sets up a contrasting statement; the intended relation is causal, not adversative.
**Faster approach:** Use structural elimination: determine whether the blank needs a causal/result, example, time-sequence, or contrast connector and eliminate choices that don’t match that relation.'),
  ('4bb96d53-e256-5940-a12b-833ce8ff0131', 3, null, '**Choice D is correct.** The second sentence narrows and specifies the general aim stated in the first sentence by naming the three plant subtypes (graminoids, forbs, and browse). The transition "Specifically," signals that the following clause gives a precise detail about the researchers'' aim, so it is the most logical and coherent choice.
**Choice A is incorrect.** "Instead," indicates contrast or an alternative, but the second sentence does not contrast with the first; it provides a more detailed description of the same aim.
**Choice B is incorrect.** "All the same," also signals a concession or contrast, which does not match the role of the second sentence.
**Choice C is incorrect.** "Therefore," indicates a conclusion based on previous information; here the second sentence is not a conclusion but a specific elaboration of the researchers'' aim.
**Faster approach:** When one sentence gives a general statement and the next names specifics, choose a specificity transition like "Specifically."'),
  ('25a8006c-673e-5d3e-8504-86507093c37c', 3, null, '**Choice D is correct.** The preceding clause claims that the pen name accomplished "far more than simply concealing his authorship," so the sentence that follows should reinforce and clarify that stronger point. "Indeed," signals confirmation and emphasis, and it smoothly introduces the statement that the name "wasn’t an arbitrary pen name but rather a complex rhetorical strategy," which restates and strengthens the prior idea.
**Choice A is incorrect.** "Conversely" indicates a contrast or opposing idea, but the following clause supports rather than opposes the claim that the name served a larger purpose.
**Choice B is incorrect.** "In addition" adds another separate point; here the writer is emphasizing and explicating the preceding claim, not simply adding an extra fact.
**Choice C is incorrect.** "However" would introduce a concession or contradiction, which conflicts with the supportive explanatory relationship needed between the two clauses.
**Faster approach:** For transitions, identify whether the next clause will contrast, add, or reinforce the previous idea; then choose a word that matches (contrast → however/conversely; add → in addition; reinforce → indeed/in fact).'),
  ('51c1acff-31a3-58eb-9f29-21f5b078870a', 3, null, '**Choice D is correct.** It directly compares the two foods using the relevant quantitative information from the notes: kale has $120 \text{mg}$ of vitamin C per $100 \text{g}$ while apricots have only $10 \text{mg}$ per $100 \text{g}$, so kale provides substantially more vitamin C per equal mass and therefore refutes the claim that apricots are a better source.
**Choice A is incorrect.** Although it gives the amount of vitamin C in kale, it does not compare kale to apricots and therefore does not refute the claim that apricots are a better source.
**Choice B is incorrect.** Stating that both contain ascorbic acid only shows they are both sources; it gives no information about which is a better source.
**Choice C is incorrect.** This notes that humans must obtain vitamin C from foods like kale and apricots, but it does not address which food provides more vitamin C and so fails to refute the claim.
**Faster approach:** Compare the stated amounts per equal mass (mg per 100 g); the larger mg/100 g value shows the better source.'),
  ('ec8b46a8-997a-5ffc-b75f-2817d1cb767f', 1, null, '**Choice B is correct.** It directly uses the given facts to provide a concrete example: the passage lists Bear Trap Meadow as one of the SNOTEL sites and says there are about 90 such stations in Wyoming, so stating "The SNOTEL site at Bear Trap Meadow is one of around 90 automated snow measurement stations in Wyoming" clearly and accurately gives an example of a SNOTEL site.
**Choice A is incorrect.** Although it restates a purpose of SNOTEL data, it does not provide a specific example of a SNOTEL site.
**Choice C is incorrect.** It identifies who maintains the stations and what they are called, but it doesn’t give a named example of a site.
**Choice D is incorrect.** It describes SNOTEL sites generally and their location but does not provide a specific example (a named site) as requested.
**Faster approach:** Look for the answer that names a specific site (Bear Trap Meadow); eliminate choices that only describe function, location, or personnel.'),
  ('56936cf7-c8d1-567e-b4eb-c141ccdb6dcd', 2, null, '**Choice C is correct.** It ties together the two relevant facts from the notes: a nautical mile corresponds to one minute of latitude (so it directly relates to the coordinate grid on nautical charts) and those charts use latitude and longitude to take Earth’s curvature into account. Because nautical miles align with the coordinate system that already accounts for curvature, they provide an efficient, practical unit for calculating distances at sea.
**Choice A is incorrect.** Although it correctly states that a nautical mile equals one minute of latitude and that charts use that grid, it doesn’t explain why that makes nautical miles especially useful for seafaring navigation (it omits the role of accounting for Earth’s curvature).
**Choice B is incorrect.** It explains why nautical charts are more accurate than flat maps, but it never connects that point to why nautical miles themselves are used, so it fails to answer the question directly.
**Choice D is incorrect.** It incorrectly asserts that measuring with latitude and longitude does not take Earth’s curvature into account; the notes explicitly say that measuring distances with coordinates does take curvature into account, so D contradicts the provided information.
**Faster approach:** Look for the answer that links the nautical mile to the latitude/longitude grid and notes that the grid accounts for Earth’s curvature—answers that make both connections are correct.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

