insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('11d5f197-78ca-5411-a147-8cba841d2247', 'c85e553e-ec8c-568b-a734-81b37d7904ec', 'For the linear function g, the table shows four values of x and their corresponding values of g(x). The function can be written as g(x) = mx + b, where m and b are constants. What is the value of b?', '["3", "12", "24", "27"]'::jsonb, 1, '| x | g(x) |
| 1 | 24 |
| 2 | 21 |
| 3 | 18 |
| 4 | 15 |'),
  ('80e00f07-97ed-5ae7-b626-c62c43e16605', 'c85e553e-ec8c-568b-a734-81b37d7904ec', '$h(x) = \frac{1}{2}(x)(87)$
The given function h represents the area, in square inches, of a triangle with a base of x inches and a fixed height. What is the height, in inches, of the triangle?', '["$\\frac{1}{89}$", "$\\frac{89}{2}$", "87", "178"]'::jsonb, 2, null),
  ('b15f4968-4e4f-5486-8ebd-cac3d91fd9fe', 'c85e553e-ec8c-568b-a734-81b37d7904ec', 'To win a game show, a contestant needs to score at least 70 total points from two rounds. Correct responses in the first round are worth 3 points each, and correct responses in the second round are worth 9 points each. Which inequality models this situation, where $f$ is the number of correct responses in the first round and $s$ is the number of correct responses in the second round?', '["$f + s \\le 70$", "$3f + 9s \\ge 70$", "$9f + s \\ge 70$", "$9f + 3s \\le 70$"]'::jsonb, 3, null),
  ('7d0002e5-5658-5407-963e-e12dc22f36a1', 'c85e553e-ec8c-568b-a734-81b37d7904ec', 'Note: Figure not drawn to scale. In the figure shown, the length of <u>AB</u> is 48. Which statement provides sufficient information to prove that triangle ABC is isosceles?', '["The length of <u>AC</u> is 24.", "The length of <u>BC</u> is 48.", "The measure of angle A is 70°.", "The sum of the measures of angles A, B, and C is 180°."]'::jsonb, 4, '![figure](/q/aug25/001.webp)'),
  ('b2df0dfd-a032-529e-aabd-3cea2fb23466', 'c85e553e-ec8c-568b-a734-81b37d7904ec', 'The function $f$ is defined by $f(x)$ = $8(3)\frac{-x}{7}$. What is the value of $f(14)$?', '["$-72$", "$-48$", "$\\frac{1}{576}$", "$\\frac{8}{9}$"]'::jsonb, 5, null),
  ('e934d667-a3f6-5ba8-8a59-d0d8d3ffb478', 'c85e553e-ec8c-568b-a734-81b37d7904ec', 'In 2010, a skating team had a total of 51 skaters, each classified as either advanced or intermediate. From 2010 to 2020, the number of advanced skaters on the team increased by approximately 59%, and the number of intermediate skaters on the team increased by approximately 48%. The total number of skaters on the team increased by approximately 53%. Which equation best represents this situation, where a represents the number of advanced skaters on the team in 2010 and b represents the number of intermediate skaters on the team in 2010?', '["$1.48a + 1.59b = 51(1.53)$", "$1.59a + 1.48b = 51(1.53)$", "$1.53a + 0.59b = 51(1.48)$", "$1.59a + 1.53b = 51(1.48)$"]'::jsonb, 6, null),
  ('3731e815-20a5-5187-9cdb-cf4806f568ca', 'c85e553e-ec8c-568b-a734-81b37d7904ec', 'For a survey, a sample of 332 people was selected at random from all registered voters in a county. Based on the survey, it is estimated that 84% of all registered voters in the county are in favor of a new law, with an associated margin of error of 3.94%. Which of the following best describes the plausible values for the percent of all registered voters in the county who are in favor of the new law?', '["Any value greater than 80.06% and less than 87.94%", "Any value greater than 80.06%", "Any value less than 80.06% or greater than 87.94%", "Any value less than 87.94%"]'::jsonb, 7, null),
  ('a0cd6f5e-b5e3-54cf-941d-b0f846314404', 'c85e553e-ec8c-568b-a734-81b37d7904ec', 'An artist made 10 pieces of pottery using 36 pounds of clay. The pottery included only bowls and vases. Each bowl used 4 pounds of clay and each vase used 2 pounds of clay. How many vases did the artist make?', '["2", "4", "6", "8"]'::jsonb, 8, null),
  ('576c507a-54cb-5148-87e4-ac13b0fd9258', 'c85e553e-ec8c-568b-a734-81b37d7904ec', 'Which expression is a factor of $x^{3} + x^{2}y + xy^{8} + y^{9}$?', '["$x^{3} + y^{9}$", "$x^{3} + y^{8}$", "$x^{2} + y^{9}$", "$x^{2} + y^{8}$"]'::jsonb, 9, null),
  ('0df0bcf4-92d0-5f1c-b6a6-8cdeecca547a', 'c85e553e-ec8c-568b-a734-81b37d7904ec', 'The measure of angle $S$ is $\frac{4π}{11}$ radians. The measure of angle $T$ is 3 times the measure of angle $S$. Which expression represents the measure, in **degrees** , of angle $T$ ?', '["$\\frac{4}{11}(90)(3)$", "$\\frac{4}{11}(180)(3)$", "$\\frac{4}{11π}(90)(3)$", "$\\frac{4π}{11}(180)(3)$"]'::jsonb, 10, null),
  ('b84d1096-ba29-5080-9e22-3db8018563bc', 'c85e553e-ec8c-568b-a734-81b37d7904ec', 'For the positive quantities h, j, and k, 15% of h is equivalent to 20% of j, and j is equivalent to 60% of k. What percentage of k is h? (Disregard the % sign when entering your answer. For example, if your answer is 39%, enter 39.)', '[]'::jsonb, 11, null),
  ('1072e013-1fa5-5668-8597-314451cb38ac', 'c85e553e-ec8c-568b-a734-81b37d7904ec', 'The graphs of the equations in the given system intersect at the point $(x,y)$ in the $xy$-plane. What is a possible value of $y$?
$y - x = 47$
$y = x^{2} - 45x$', '["47", "48", "93", "94"]'::jsonb, 12, null),
  ('5d0a99b0-c2d6-5deb-b40d-2c1ebcb3d99c', 'c85e553e-ec8c-568b-a734-81b37d7904ec', 'An object travels $x$ inches in $y$ seconds. At this rate, which expression represents the time, in seconds, it takes the object to travel a distance of $12x$ inches?', '["$\\frac{12}{y}$", "$\\frac{y}{12}$", "$12y$", "$y + 12$"]'::jsonb, 13, null),
  ('690993e4-1f10-54d2-8c8b-e63736f0e3d6', 'c85e553e-ec8c-568b-a734-81b37d7904ec', 'The number of bacteria in a growth medium is expected to increase by 150% every 2 hours during a period of observation. The number of bacteria in the growth medium was estimated to be 7,000 when the period of observation began. Which function P gives the expected number of bacteria in this growth medium t hours after the period of observation began?', '["$P(t) = 7,000(1.50) \\frac{t}{2}$", "$P(t) = 7,000(1.50)^{2t}$", "$P(t) = 7,000(2.50) \\frac{t}{2}$", "$P(t) = 7,000(2.50)^{2t}$"]'::jsonb, 14, null),
  ('38fd1f71-c126-5b46-9e2d-4c99d4c03289', 'c85e553e-ec8c-568b-a734-81b37d7904ec', 'Line p is defined by $kx + 7y = 16$. Line p passes through the points $(r,0)$ and $(0,t)$ in the xy-plane, where k, r, and t are nonzero constants and r is not equal to t. Which expression represents the value of k?', '["$\\frac{16}{t}$", "$\\frac{16}{r}$", "$\\frac{7}{t}$", "$\\frac{7}{r}$"]'::jsonb, 15, null),
  ('c712dc2a-ae77-50ab-8072-a923e150e4f6', 'c85e553e-ec8c-568b-a734-81b37d7904ec', '$nx + 3t = -3x + 4n$
In the given equation, n and t are constants. The equation has no solution. What **CANNOT** be the value of n + t ?', '[]'::jsonb, 16, null),
  ('e7475589-99b2-5aa0-82e5-228393d56769', 'c85e553e-ec8c-568b-a734-81b37d7904ec', 'Which of the following equations is the most appropriate linear model for the data shown?', '["$d = -48.1 + 2.02t$", "$d = 148.1 + 2.02t$", "$d = 371.8 + 2.02t$", "$d = 406.8 + 2.02t$"]'::jsonb, 17, '![figure](/q/aug25/002.webp)

The scatterplot shows the relationship between two variables, t and d.'),
  ('a561962f-de82-57a1-b189-cf0111169d41', 'c85e553e-ec8c-568b-a734-81b37d7904ec', 'The table shows the volume of two similar solids, right circular cylinder A and right circular cylinder B. The radius of right circular cylinder A is 2 units. The surface area of right circular cylinder A is $kπ$ square units, and the surface area of right circular cylinder B is $nπ$ square units, where $k$ and $n$ are constants. What is the value of $n - k$? (The surface area of a right circular cylinder with radius $r$ and height $h$ is $2πr^{2} + 2πrh$.)', '[]'::jsonb, 18, '| Right circular cylinder | Volume (in cubic units) |
| **Right circular cylinder A** | **32π** |
| **Right circular cylinder B** | **864π** |'),
  ('3ac04400-ebf0-50df-98fa-9e8eaf76e8c3', 'c85e553e-ec8c-568b-a734-81b37d7904ec', 'A quadratic function models the height, in feet, of an object above the ground in terms of the time, in seconds, after the object was launched. According to the model, the object was launched from a height of 0 feet and reached its maximum height of 1,600 feet 10 seconds after it was launched. Based on the model, what was the height, in feet, of the object 13 seconds after it was launched?', '[]'::jsonb, 19, null),
  ('354e05f6-5a7b-5090-934e-9b14bec2347a', 'c85e553e-ec8c-568b-a734-81b37d7904ec', 'The table shows three values of x and their corresponding values of y, where y = f(x) + 6 and f is a quadratic function. What is the y-coordinate of the y-intercept of the graph of y = f(x) in the xy-plane?', '[]'::jsonb, 20, '| x | y |
| 16 | -7 |
| 19 | 11 |
| 22 | -7 |'),
  ('2ac9d8b6-d43a-50d6-a500-34a600149bc6', 'c85e553e-ec8c-568b-a734-81b37d7904ec', 'Javier deposits $55$ USD in a savings account at the end of each week. At the beginning of the 1st week of a year there was $900$ USD in that savings account. How much money, in dollars, will be in the account at the end of the 6th week of the year?', '["570", "955", "961", "1,23"]'::jsonb, 21, null),
  ('696f7e56-9e14-5ced-9f33-5a5e38055b87', 'c85e553e-ec8c-568b-a734-81b37d7904ec', 'In the figure, line $q$ is parallel to line $r$, and both lines are intersected by transversal line $s$. If the relationship between the marked angles is given by the equation $y = 2x + 7$, what is the value of $x$?', '["22", "29", "61", "71"]'::jsonb, 22, '![figure](/q/aug25/003.webp)')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('11d5f197-78ca-5411-a147-8cba841d2247', 3, null, '**Choice D is correct.** To find the value of $b$, we need to express the linear function $g(x) = mx + b$ using the values from the table.
First, we will determine the slope $m$ using two points from the table. Let’s use the points $(1,24)$ and $(4,15)$. The slope formula is given by:
$m = \frac{g(x_{2}) - g(x_{1})}{x_{2} - x_{1}} = \frac{15 - 24}{4 - 1} = \frac{-9}{3} = -3.$
Now that we have $m = -3$, we can substitute $m$ and one point into the linear equation to find $b$. We''ll use the point $(1,24)$:
$g(1) = -3(1) + b.$
Substituting $g(1) = 24$ gives:
$24 = -3 + b.$
By solving for $b$, we add 3 to both sides:
$b = 24 + 3 = 27.$
Thus, the value of $b$ is 27, confirming that choice D is correct.
Now, let’s briefly discuss why the other options are incorrect:
**Choice A (3):** This value does not fit the calculated $b = 27$.
**Choice B (12):** Similarly, this value does not satisfy the linear equation based on our calculations. **Choice C (24):** While this is a value of $g(x)$ for $x = 1$, it does not represent the y-intercept $b$ of the function.'),
  ('80e00f07-97ed-5ae7-b626-c62c43e16605', 2, null, '**Choice C is correct.** The area of a triangle is $A = \frac{1}{2}(\text{base})(\text{height})$. Here $h(x) = \frac{1}{2}x(87)$ matches that form with base $x$ and the other factor $87$ representing the height, so the height is $87$ inches.
**Choice A is incorrect.** $\frac{1}{89}$ is not present in the formula; there is no division by 89 and the given factor is 87, not $\frac{1}{89}$.
**Choice B is incorrect.** $\frac{89}{2}$ is not equal to 87 and does not appear in the expression; the $\frac{1}{2}$ multiplies $x$, not the height.
**Choice D is incorrect.** 178 is $2 \cdot 89$ and is not a factor in the given expression; the only factor paired with $x$ (besides $\frac{1}{2}$) is 87, so the height is 87, not 178.
**Faster approach:** Match the given expression to $\frac{1}{2}(\text{base})(\text{height})$; the factor that is not the base or $\frac{1}{2}$ is the height.'),
  ('b15f4968-4e4f-5486-8ebd-cac3d91fd9fe', 1, null, '**Choice B is correct.** The total score is the sum of points from each round: each first-round correct response contributes $3$ points and each second-round correct response contributes $9$ points. The requirement "at least $70$" means the total must be greater than or equal to $70$, so the inequality is $3f + 9s \ge 70$.
**Choice A is incorrect.** $f + s \le 70$ treats each correct response as worth 1 point and uses ``less than or equal to,'''' which contradicts both the point values and the required minimum score.
**Choice C is incorrect.** $9f + s \ge 70$ swaps the point values for the rounds (treats first-round responses as worth 9 and second-round as worth 1), so it does not match the given scoring.
**Choice D is incorrect.** $9f + 3s \le 70$ also swaps the point values and uses ``less than or equal to,'''' which conflicts with the required minimum of 70 points.
**Faster approach:** Translate word-for-word: "at least 70" → $\ge 70$; "3 points each" for $f$ → $3f$; "9 points each" for $s$ → $9s$; combine as $3f + 9s \ge 70$ and choose that answer.'),
  ('7d0002e5-5658-5407-963e-e12dc22f36a1', 1, null, '**Choice B is correct.** If BC = 48, then BC = AB, so two sides of triangle ABC are congruent. By the definition of an isosceles triangle (a triangle with at least two equal sides), triangle ABC is isosceles.
**Choice A is incorrect.** AC = 24 only gives a specific length for AC; it does not show AC equals either of the other sides, so it does not establish that two sides are congruent.
**Choice C is incorrect.** Knowing angle A = 70° gives an angle measure but does not guarantee any pair of sides are equal, so it cannot alone prove the triangle is isosceles.
**Choice D is incorrect.** The sum of the measures of angles A, B, and C being 180° is true for every triangle and therefore provides no information about side equality; it cannot prove the triangle is isosceles.
**Faster approach:** To prove a triangle is isosceles, look for a statement that makes two side lengths equal (showing two congruent sides is sufficient).'),
  ('b2df0dfd-a032-529e-aabd-3cea2fb23466', 3, null, '**Choice D is correct.** Substitute $x = 14$ into $f(x) = 8 \cdot 3^{-x/7}$. That gives $f(14) = 8 \cdot 3^{-14/7} = 8 \cdot 3^{-2} = 8 \cdot \frac{1}{9} =$ $\frac{8}{9}$.
**Choice A is incorrect.** $-72$ would require multiplying by a negative or a much larger power; there is no negative sign in the function and the value is less than 8, so $-72$ is impossible.
**Choice B is incorrect.** $-48$ is also negative and far too large in magnitude; the given exponential yields a positive value less than 8, so $-48$ cannot be correct.
**Choice C is incorrect.** $\frac{1}{576}$ is much smaller than the correct value; that would correspond to $8 \cdot$ $3^{-\text{a} \text{much} \text{larger} \text{exponent}}$, not $3^{-2}$.
**Faster approach:** Directly plug in $x = 14$ and use exponent rules: $3^{-14/7} = 3^{-2} = 1/9$, so multiply by 8 to get $8/9$.'),
  ('e934d667-a3f6-5ba8-8a59-d0d8d3ffb478', 1, null, '**Choice B is correct.** If $a$ is the number of advanced skaters in 2010, the number in 2020 is $1.59a$ (a 59% increase). If $b$ is the number of intermediate skaters in 2010, the number in 2020 is $1.48b$ (a 48% increase). The total in 2010 was $51$, and the total in 2020 is $51(1.53)$ (a 53% increase). So the equation equating the 2020 totals is $1.59a + 1.48b = 51(1.53)$.
**Choice A is incorrect.** It swaps the 1.48 and 1.59 factors with the wrong variables (it applies 1.48 to $a$ and 1.59 to $b$), so it does not match the given percent changes.
**Choice C is incorrect.** It uses 1.53 and 0.59 on the left and 1.48 on the right, which misapplies the percent changes and uses 0.59 (59% of the original) instead of 1.59 (original plus 59%).
**Choice D is incorrect.** It applies the 1.53 factor to $b$ on the left instead of to the total on the right, so it does not represent the total 53% increase.
**Faster approach:** Multiply each 2010 quantity by its 2020 multiplier (1 + percent increase) and set their sum equal to 51 times 1.53. This directly yields $1.59a + 1.48b = 51(1.53)$.'),
  ('3731e815-20a5-5187-9cdb-cf4806f568ca', 0, null, '**Choice A is correct.** The margin of error gives a plausible interval about the sample estimate: $84% \pm 3.94%$. Calculating the endpoints gives a lower bound $84 - 3.94 = 80.06%$ and an upper bound $84 + 3.94 = 87.94%$. So plausible percents are values between 80.06% and 87.94%, which Choice A describes.
**Choice B is incorrect.** It describes all values greater than 80.06%, which would include values above 87.94% that are not within the margin-of-error interval.
**Choice C is incorrect.** It describes values outside the interval (less than 80.06% or greater than 87.94%), but the plausible values are inside that interval, not outside it.
**Choice D is incorrect.** It describes all values less than 87.94%, which would include values below 80.06% that are not supported by the margin-of-error interval.
**Faster approach:** Immediately add and subtract the margin of error from the point estimate to form the interval $\text{estimate} \pm \text{margin}$; choose the answer that matches that interval.'),
  ('a0cd6f5e-b5e3-54cf-941d-b0f846314404', 0, null, '**Choice A is correct.** Let $b$ be the number of bowls and $v$ the number of vases. The problem gives the system $b + v = 10$ and $4b + 2v = 36$. Substitute $b = 10 - v$ into the second equation: $4(10 - v) + 2v = 36$, so $40 -$ $4v + 2v = 36$, $-2v = -4$, and $v = 2$. Thus the artist made 2 vases.
**Choice B is incorrect.** If $v = 4$, then $b = 6$ and clay used would be $4(6) + 2(4) = 24 + 8 = 32$, not 36.
**Choice C is incorrect.** If $v = 6$, then $b = 4$ and clay used would be $4(4) + 2(6) = 16 + 12 = 28$, not 36.
**Choice D is incorrect.** If $v = 8$, then $b = 2$ and clay used would be $4(2) + 2(8) = 8 + 16 = 24$, not 36.
**Faster approach:** Use substitution or compare to the all-bowls case: 10 bowls would use $10 \cdot 4 = 40$ lb; actual use is 4 lb less, and each vase saves $2$ lb relative to a bowl, so $4/2 = 2$ vases. This quick difference method works for every similar two-item clay/weight problem.'),
  ('576c507a-54cb-5148-87e4-ac13b0fd9258', 3, null, '**Choice D is correct.** Factor by grouping: $x^{3} + x^{2}y + xy^{8} + y^{9} = (x^{3} + x^{2}y) + (xy^{8} + y^{9}) = x^{2}(x + y) +$ $y^{8}(x + y) = (x + y)(x^{2} + y^{8})$, so $x^{2} + y^{8}$ is a factor.
**Choice A is incorrect.** $x^{3} + y^{9}$ does not appear as a factor because the grouped factorization produces $x^{2} +$ $y^{8}$, not $x^{3} + y^{9}$, and $x^{3} + y^{9}$ does not divide the original polynomial.
**Choice B is incorrect.** $x^{3} + y^{8}$ is not a factor: degrees and term structure don’t match the grouped factorization, and there is no algebraic step producing $x^{3} + y^{8}$.
**Choice C is incorrect.** $x^{2} + y^{9}$ is not a factor; the constant powers of $y$ in the second group give $y^{8}$, not $y^{9}$, so $x^{2} + y^{9}$ cannot factor the polynomial.
**Faster approach:** Try factoring by grouping immediately: split into two pairs, factor each pair, and look for the common binomial factor $(x + y)$ to reveal the other factor.'),
  ('0df0bcf4-92d0-5f1c-b6a6-8cdeecca547a', 1, null, '**Choice B is correct.** Angle S measures $\frac{4π}{11}$ radians, so angle T measures $3(\frac{4π}{11}) = \frac{12π}{11}$ radians. To convert radians to degrees multiply by $\frac{180}{π}$, so the degree measure is $\frac{12π}{11} \cdot \frac{180}{π} = \frac{12\cdot 180}{11}$. Factoring $12$ as $4 \cdot 3$ gives $\frac{4}{11}(180)(3)$, which matches Choice B.
**Choice A is incorrect.** It uses $90$ instead of $180$ to convert radians to degrees; the correct conversion factor is $180/π$, not $90/π$.
**Choice C is incorrect.** It introduces an extra $π$ in the denominator and uses $90$, which does not represent the correct radian-to-degree conversion.
**Choice D is incorrect.** It leaves a factor of $π$ in the expression; converting to degrees requires the $π$ to cancel with the $π$ in the denominator of $180/π$.
**Faster approach:** Multiply the radian measure by $180/π$ and cancel any $π$ before multiplying numbers; here canceling $π$ first gives $\frac{12\cdot 180}{11} = \frac{4}{11}(180)(3)$ immediately.'),
  ('b84d1096-ba29-5080-9e22-3db8018563bc', null, array['80']::text[], '**The correct answer is 80.** Let percents be decimals. From 15% of $h$ = 20% of $j$, $0.15h = 0.20j$, so $h =$ $(0.20/0.15)j = (4/3)j$. From $j = 60%$ of $k$, $j = 0.60k$. Substitute to get $h = (4/3)(0.60k) = (4/3)(3/5)k =$ $(4/5)k = 0.80k$, so $h$ is 80% of $k$.
**Faster approach:** Work with simple numbers. Let $k = 100$, so $j = 60$ (60% of 100). Since 15% of $h$ equals 20% of $j$, scale $h$ so $0.15h = 0.20(60) = 12$, so $h = 12/0.15 = 80$, which is 80% of 100. This “set $k$=100” strategy works for any percent-of relationships.'),
  ('1072e013-1fa5-5668-8597-314451cb38ac', 3, null, '**Choice D is correct.** Substitute $y = x + 47$ from the first equation into the second: $x + 47 = x^{2} - 45x$. Rearranging gives $0 = x^{2} - 46x - 47$. The quadratic formula (or factoring) yields $x = \frac{46\pm \sqrt{46^{2}+4\cdot 47}}{2} =$ $\frac{46\pm \sqrt{2304}}{2} = \frac{46\pm 48}{2}$, so $x = 47$ or $x = -1$. Then $y = x + 47$ gives $y = 94$ for $x = 47$ (and $y = 46$ for $x = -1$). The only choice listed that matches is $94$.
**Choice A is incorrect.** If $y = 47$, then $x = 0$ from $y = x + 47$, but $x = 0$ does not satisfy $y = x^{2} - 45x$ (that would give $y = 0$), so 47 is not an intersection $y$-value.
**Choice B is incorrect.** If $y = 48$, then $x = 1$, but $x = 1$ gives $y = 1 - 45 = -44$ in the quadratic, so 48 is not valid.
**Choice C is incorrect.** If $y = 93$, then $x = 46$, but $x = 46$ gives $y = 46^{2} - 45 \cdot 46 = 46$, not 93, so 93 is not an intersection $y$-value.
**Faster approach:** Substitute the linear expression for $y$ into the quadratic to get a quadratic in $x$, then solve (factor, use the quadratic formula, or check for a perfect-square discriminant) and compute $y = x + 47$. This method works for every such system.'),
  ('5d0a99b0-c2d6-5deb-b40d-2c1ebcb3d99c', 2, null, '**Choice C is correct.** The object’s speed is $\frac{x}{y}$ inches per second, so the time to travel $12x$ inches is $\frac{12x}{(x/y)} =$ $12x \cdot \frac{y}{x} = 12y$ seconds.
**Choice A is incorrect.** $\frac{12}{y}$ has units of seconds only if $12$ carried inches, but here $12$ is a unitless factor; dividing 12 by $y$ does not produce the required scaling of the given time $y$.
**Choice B is incorrect.** $\frac{y}{12}$ is the time to travel $\frac{x}{12}$ inches (not $12x$), so it scales the time in the wrong direction. **Choice D is incorrect.** $y + 12$ adds 12 seconds to the original time; travel time scales proportionally with distance, so times additively increasing by a constant is not correct.
**Faster approach:** Use proportionality: if $x$ inches takes $y$ seconds, then $12x$ inches takes $12 \times y$ seconds—scale the time by the same factor as the distance.'),
  ('690993e4-1f10-54d2-8c8b-e63736f0e3d6', 2, null, '**Choice C is correct.** An increase of 150% means the new amount is 100% + 150% = 250% of the original, i.e., a multiplicative factor of $2.5$ every 2 hours. For exponential growth with factor per 2-hour period, use $P(t) =$ $7000 \cdot (2.5)^{t/2}$, because the number of 2-hour periods in $t$ hours is $t/2$.
**Choice A is incorrect.** $1.50$ is a factor for a 50% increase, not a 150% increase; using $(1.50)^{t/2}$ understates the growth.
**Choice B is incorrect.** $(1.50)^{2t}$ both uses the wrong growth factor (1.50) and the wrong exponent (it would imply the factor applies every $1/2$ hour rather than every 2 hours).
**Choice D is incorrect.** $(2.50)^{2t}$ uses the correct per-period factor but the exponent $2t$ implies the factor is applied twice per hour (every $1/2$ hour), so it grows far too rapidly.
**Faster approach:** Identify the multiplicative factor per given period (150% increase → factor $2.5$) and raise it to the number of those periods, i.e., exponent $t/(2\text{hours})$.'),
  ('38fd1f71-c126-5b46-9e2d-4c99d4c03289', 1, null, '**Choice B is correct.** The x-intercept (r,0) lies on the line $kx + 7y = 16$. Plugging in $y = 0$ and $x = r$ gives $kr = 16$, so $k = \frac{16}{r}$.
**Choice A is incorrect.** Plugging in the y-intercept $(0,t)$ gives $7t = 16$, so $t = \frac{16}{7}$; $k = \frac{16}{t}$ would imply $k =$ $\frac{16}{16/7} = 7$, which is not generally true unless $r = 16/7$, but $r$ is the x-intercept and need not equal $t$. **Choice C is incorrect.** $\frac{7}{t}$ equals $\frac{7}{16/7} = \frac{49}{16}$ using $t = 16/7$, which does not equal $k = \frac{16}{r}$ in general. **Choice D is incorrect.** $\frac{7}{r}$ does not follow from $kr = 16$; solving that gives $k = \frac{16}{r}$, not $\frac{7}{r}$.
**Faster approach:** Use the x-intercept directly: set $y = 0$ so the equation becomes $kr = 16$, then solve for $k$ to get $k = \frac{16}{r}$—a one-step substitution that works for any line given an x-intercept.'),
  ('c712dc2a-ae77-50ab-8072-a923e150e4f6', null, array['-7']::text[], '**The correct answer is -7.** Rearrange $nx + 3t = -3x + 4n$ to collect $x$ terms: $x(n + 3) = 4n - 3t$. For the equation to have no solution, the coefficient of $x$ must be $0$ while the constant term is nonzero. So $n + 3 = 0$, giving $n = -3$, and $4n - 3t \ne 0$, which with $n = -3$ is $-12 - 3t \ne 0$, so $t \ne -4$. Thus $n + t = -3 + t$ can be any value except when $t = -4$, which would give $n + t = -7$; that value cannot occur when the equation has no solution.
**Faster approach:** Force the $x$ coefficient to zero ($n + 3 = 0$) and then require the resulting constant not be zero; compute $n + t$ from $n = -3$ and exclude the value coming from the forbidden $t = -4$.'),
  ('e7475589-99b2-5aa0-82e5-228393d56769', 3, null, '**Choice D is correct.** The slope of the best-fit line is given as $2.02$ in every choice, so identify the y-intercept by reading the graph. At $t = 0$ the red line is just above $400$, and choice D has intercept $406.8$. Checking a second point: at $t = 100$ the model $d = 406.8 + 2.02(100) = 406.8 + 202 = 608.8$, which matches the line near the top of the plot (about 600–610). Thus choice D matches the visual intercept and line placement.
**Choice A is incorrect.** Its intercept $-48.1$ would place the line far below the data at $t = 0$, contradicting the plot.
**Choice B is incorrect.** Its intercept $148.1$ is much too low; the red line at $t = 0$ is near $400$, not near $150$.
**Choice C is incorrect.** Its intercept $371.8$ is lower than the plotted line at $t = 0$ (the line is noticeably above $400$), so C underestimates the data.
**Faster approach:** Read the y-intercept of the drawn best-fit line directly (or plug a clear x-value like $t = 0$ or $t = 100$ into each choice to see which produces the plotted y-value) — here that immediately selects the option with intercept ~407.'),
  ('a561962f-de82-57a1-b189-cf0111169d41', null, array['320']::text[], '**The correct answer is 320.** The volume ratio is $\frac{864π}{32π} = 27$, so the linear scale factor is $\sqrt{^{3} 27} = 3$. Cylinder A has radius $r_{A} = 2$, so $r_{B} = 3 \cdot 2 = 6$. From $V = πr^{2}h$, for A: $32π = π(2^{2})h_{A}$ so $h_{A} = 8$; for B: $864π = π(6^{2})h_{B}$ so $h_{B} = 24$. Surface area formula gives $kπ = 2π(2^{2}) + 2π(2)(8) = 8π + 32π = 40π$, so $k = 40$. For B: $nπ =$ $2π(6^{2}) + 2π(6)(24) = 72π + 288π = 360π$, so $n = 360$. Thus $n - k = 360 - 40 = 320$.
**Faster approach:** Surface area scales by the square of the linear scale factor. With scale factor $3$, surface areas multiply by $3^{2} = 9$, so $n = 9k$ and $n - k = 8k$. Compute $k$ quickly from A: $k = 2(2^{2}) + 2(2)(h_{A})$ with $h_{A} = 32π/(π \cdot 4) = 8$, giving $k = 40$, then $8k = 320$.'),
  ('3ac04400-ebf0-50df-98fa-9e8eaf76e8c3', null, array['1456']::text[], '**The correct answer is 1456.** Let the height be given by a quadratic h(t) with vertex at (10,1600) and h(0)=0. In vertex form, $h(t) = a(t - 10)^{2} + 1600$. Using $h(0) = 0$ gives $0 = a(0 - 10)^{2} + 1600 = 100a + 1600$, so $a =$ $-16$. Thus $h(t) = -16(t - 10)^{2} + 1600$. Evaluate at $t = 13$: $h(13) = -16(13 - 10)^{2} + 1600 = -16(9) +$
$1600 = -144 + 1600 = 1456.$
**Faster approach:** Use vertex form $h(t) = a(t - 10)^{2} + 1600$ and plug in the known point $(0,0)$ to find $a$ quickly, then substitute $t = 13$. This avoids expanding and minimizes arithmetic.'),
  ('354e05f6-5a7b-5090-934e-9b14bec2347a', null, array['-717']::text[], '**The correct answer is -717.** Because the table gives values of y = f(x) + 6, first compute f(x) by subtracting 6 from each listed y: f(16) = -13, f(19) = 5, and f(22) = -13. The equal values at x = 16 and x = 22 show the axis of symmetry is the midpoint x = 19, so the vertex is at (19, 5). Write f in vertex form as $f(x) = a(x - 19)^{2} + 5$. Substitute x = 16: $-13 = a(16 - 19)^{2} + 5 = 9a + 5$, so $9a = -18$ and $a = -2$. Thus $f(x) = -2(x - 19)^{2} + 5$, and the y-intercept is $f(0) = -2(0 - 19)^{2} + 5 = -2(361) + 5 = -722 + 5 = -717$.
**Faster approach:** Recognize symmetry: find the midpoint of the two equal f-values to get the vertex x-coordinate, form $f(x) = a(x - h)^{2} + k$, solve for a using one point, then evaluate at x=0. This sequence works for any quadratic given three points where two y-values match.'),
  ('2ac9d8b6-d43a-50d6-a500-34a600149bc6', 3, null, '**Choice D is correct.** The account starts with $900$ and Javier makes a deposit of $55$ at the end of each week for 6 weeks, so the amount at the end of week 6 is $900 + 6 \times 55 = 900 + 330 = 1230$. The option labeled "1,23" is intended to represent $1,230$, which matches this value.
**Choice A is incorrect.** $570$ is too small; it would correspond to $55 \times 10$ or $900 - 330$, neither of which matches the described deposits.
**Choice B is incorrect.** $955$ equals $900 + 55$, which would be the amount after only one deposit (end of week 1), not after six deposits.
**Choice C is incorrect.** $961$ is not obtainable from $900 + 55 \times n$ for any integer $n$ here; it does not equal $900 +$ $6 \times 55$.
**Faster approach:** Write an expression $900 + 55w$ and substitute $w = 6$, or compute $55 \times 6 = 330$ and add to $900$ to get $1230$.'),
  ('696f7e56-9e14-5ced-9f33-5a5e38055b87', 0, null, '**Choice A is correct.** The diagram shows the top marked angle is 51°, which corresponds to y in the equation y = 2x + 7. Substitute y = 51 to get $51 = 2x + 7$. Subtract 7 from both sides to get $44 = 2x$, then divide by 2 to find $x = 22$.
**Choice B is incorrect.** If $x = 29$ then $2x + 7 = 65$, which does not equal the given 51°.
**Choice C is incorrect.** If $x = 61$ then $2x + 7 = 129$, which is far from 51° and not consistent with the equation.
**Choice D is incorrect.** If $x = 71$ then $2x + 7 = 149$, which also does not match the 51° value of y.
**Faster approach:** Identify the marked numerical angle (51°) as y, substitute into $y = 2x + 7$, and solve the simple linear equation $51 = 2x + 7$ to get $x = 22$ — a one-step arithmetic solution for every problem of this type.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
